const uiTranslations = Object.fromEntries(Object.entries(uiRows).map(([code,row]) => [code,Object.fromEntries(row.split('|').map((value,i)=>[uiKeys[i],value]))]));
function ui(key) {
    const value = name => uiTranslations[currentLanguage]?.[name] || uiTranslations.en[name];
    if (key==='paused') return value('pause');
    if (key==='round') return getTranslation('level');
    if (key==='time') return '⏱';
    if (key==='combo') return '×';
    if (key==='balls') return '●';
    if (key==='settingsHelp') return value('select')+' → '+value('settings');
    if (key==='holdHint') return value('pause')+': '+value('hold')+' ('+(typeof settings==='undefined'?2.5:settings.holdPause/1000)+' s)';
    if (key==='autoHint') return value('scan')+': '+value('auto')+'. '+value('action')+' → '+value('select');
    if (key==='stepHint') return '② → '+value('next')+' · ① → '+value('select');
    if (key==='offHint') return 'Tab → '+value('next')+' · Enter → '+value('select')+' · '+value('hold')+' → '+value('settings');
    return value(key) || key;
}


