// GAME 1: SPACE INVADERS
class SpaceInvaders {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.player = { x: canvas.width / 2, y: canvas.height - 40, speed: 5, dir: 1 };
        this.bullets = []; this.enemyBullets = []; this.lastShot = 0;
        this.enemies = []; this.enemyDir = 1; this.enemySpeed = 1; this.createEnemies();
    }
    createEnemies() {
        this.enemies = [];
        const rows = 3 + Math.floor(this.level / 2), cols = Math.min(8, 5 + this.level);
        const w = 35, h = 25, pad = 15, sx = (canvas.width - cols * (w + pad)) / 2;
        for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++)
            this.enemies.push({ x: sx + c * (w + pad), y: 50 + r * (h + pad), w, h, type: r % 3 });
        this.enemySpeed = 1 + this.level * 0.3;
    }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: auto-move, press either to change direction
            if (input.leftPressed || input.rightPressed) { this.player.dir *= -1; playSound('move'); }
            this.player.x += this.player.speed * sm * this.player.dir;
            if (this.player.x <= 25) { this.player.x = 25; this.player.dir = 1; }
            if (this.player.x >= canvas.width - 25) { this.player.x = canvas.width - 25; this.player.dir = -1; }
        } else {
            // 2-switch: normal left/right
            if (input.left && this.player.x > 25) this.player.x -= this.player.speed * sm;
            if (input.right && this.player.x < canvas.width - 25) this.player.x += this.player.speed * sm;
        }
        if (gameNow() - this.lastShot > 500 / sm) {
            this.bullets.push({ x: this.player.x, y: this.player.y - 10 }); playSound('shoot'); this.lastShot = gameNow();
        }
        this.bullets = this.bullets.filter(b => { b.y -= 8 * sm; return b.y > 0; });
        this.enemyBullets = this.enemyBullets.filter(b => { b.y += 4 * sm; return b.y < canvas.height; });
        if (Math.random() < 0.02 * sm && this.enemies.length) {
            const e = this.enemies[Math.floor(Math.random() * this.enemies.length)];
            this.enemyBullets.push({ x: e.x + e.w / 2, y: e.y + e.h });
        }
        let edge = false;
        this.enemies.forEach(e => { e.x += this.enemyDir * this.enemySpeed * sm; if (e.x <= 0 || e.x + e.w >= canvas.width) edge = true; });
        if (edge) { this.enemyDir *= -1; this.enemies.forEach(e => { e.y += 20; if (e.y + e.h >= this.player.y) this.gameOver = true; }); }
        for (let bi=this.bullets.length-1;bi>=0;bi--) {
            const b=this.bullets[bi];
            const ei=this.enemies.findIndex(e=>b.x>e.x&&b.x<e.x+e.w&&b.y>e.y&&b.y<e.y+e.h);
            if(ei>=0){this.bullets.splice(bi,1);this.enemies.splice(ei,1);this.score+=10*this.level;playSound('hit');}
        }
        this.enemyBullets.forEach(b => { if (Math.abs(b.x - this.player.x) < 25 && Math.abs(b.y - this.player.y) < 15) this.gameOver = true; });
        if (!this.enemies.length) { this.level++; playSound('score'); this.createEnemies(); }
    }
    draw() {
        ctx.fillStyle = '#0a0a1a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        for (let i = 0; i < 50; i++) { ctx.fillStyle = '#fff'; ctx.fillRect((i * 73) % canvas.width, (i * 97) % canvas.height, 2, 2); }
        ctx.fillStyle = '#00ffff'; ctx.beginPath(); ctx.moveTo(this.player.x, this.player.y - 15);
        ctx.lineTo(this.player.x - 25, this.player.y + 10); ctx.lineTo(this.player.x + 25, this.player.y + 10); ctx.fill();
        ctx.fillStyle = '#ffff00'; this.bullets.forEach(b => ctx.fillRect(b.x - 2, b.y, 4, 15));
        ctx.fillStyle = '#ff0066'; this.enemyBullets.forEach(b => ctx.fillRect(b.x - 2, b.y, 4, 10));
        const cols = ['#ff0066', '#ff6600', '#ff00ff'];
        this.enemies.forEach(e => { ctx.fillStyle = cols[e.type]; ctx.fillRect(e.x, e.y, e.w, e.h);
            ctx.fillStyle = '#fff'; ctx.fillRect(e.x + 6, e.y + 6, 5, 5); ctx.fillRect(e.x + e.w - 11, e.y + 6, 5, 5); });
    }
}

// GAME 2: SNAKE
class Snake {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false; this.gridSize = 20; this.dir = 0;
        const sx = Math.floor(canvas.width / 2 / 20) * 20, sy = Math.floor(canvas.height / 2 / 20) * 20;
        this.snake = [{ x: sx, y: sy }, { x: sx - 20, y: sy }, { x: sx - 40, y: sy }];
        this.food = this.spawn(); this.timer = 0; this.interval = 150;
    }
    spawn() { let f; do { f = { x: Math.floor(Math.random() * (canvas.width / 20)) * 20, y: Math.floor(Math.random() * (canvas.height / 20)) * 20 };
        } while (this.snake.some(s => s.x === f.x && s.y === f.y)); return f; }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: press either button to turn right
            if (input.leftPressed || input.rightPressed) { this.dir = (this.dir + 1) % 4; playSound('move'); }
        } else {
            // 2-switch: left turns left, right turns right
            if (input.leftPressed) { this.dir = (this.dir + 3) % 4; playSound('move'); }
            if (input.rightPressed) { this.dir = (this.dir + 1) % 4; playSound('move'); }
        }
        this.timer += 16 * sm;
        if (this.timer >= this.interval) {
            this.timer = 0; const h = { ...this.snake[0] };
            if (this.dir === 0) h.x += 20; else if (this.dir === 1) h.y += 20; else if (this.dir === 2) h.x -= 20; else h.y -= 20;
            if (h.x < 0 || h.x >= canvas.width || h.y < 0 || h.y >= canvas.height || this.snake.some(s => s.x === h.x && s.y === h.y)) { this.gameOver = true; return; }
            this.snake.unshift(h);
            if (h.x === this.food.x && h.y === this.food.y) { this.score += 10; playSound('score'); this.food = this.spawn();
                if (this.score % 50 === 0) { this.level++; this.interval = Math.max(50, this.interval - 10); }
            } else this.snake.pop();
        }
    }
    draw() {
        ctx.fillStyle = '#0a0a1a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        this.snake.forEach((s, i) => { ctx.fillStyle = i === 0 ? '#00ffff' : `rgba(0,255,200,${1 - i / this.snake.length * 0.5})`;
            ctx.beginPath(); ctx.arc(s.x + 10, s.y + 10, 8, 0, Math.PI * 2); ctx.fill(); });
        ctx.fillStyle = '#ff0066'; ctx.beginPath(); ctx.arc(this.food.x + 10, this.food.y + 10, 8, 0, Math.PI * 2); ctx.fill();
    }
}

// GAME 3: BREAKOUT
class Breakout {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.paddle = { x: canvas.width / 2, y: canvas.height - 30, w: 100, h: 15, speed: 8, dir: 1 };
        this.ball = { x: canvas.width / 2, y: canvas.height - 50, r: 8, dx: 4, dy: -4 };
        this.createBricks();
    }
    createBricks() {
        this.bricks = []; const rows = 4 + this.level, cols = Math.floor(canvas.width / 70);
        const w = 60, h = 20, pad = 10, sx = (canvas.width - cols * (w + pad) + pad) / 2;
        const colors = ['#ff0066', '#ff6600', '#ffff00', '#00ff66', '#00ffff', '#6666ff'];
        for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++)
            this.bricks.push({ x: sx + c * (w + pad), y: 50 + r * (h + pad), w, h, color: colors[r % 6] });
    }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: auto-move paddle, press either to change direction
            if (input.leftPressed || input.rightPressed) { this.paddle.dir *= -1; playSound('move'); }
            this.paddle.x += this.paddle.speed * sm * this.paddle.dir;
            if (this.paddle.x <= this.paddle.w / 2) { this.paddle.x = this.paddle.w / 2; this.paddle.dir = 1; }
            if (this.paddle.x >= canvas.width - this.paddle.w / 2) { this.paddle.x = canvas.width - this.paddle.w / 2; this.paddle.dir = -1; }
        } else {
            // 2-switch: normal left/right
            if (input.left && this.paddle.x > this.paddle.w / 2) this.paddle.x -= this.paddle.speed * sm;
            if (input.right && this.paddle.x < canvas.width - this.paddle.w / 2) this.paddle.x += this.paddle.speed * sm;
        }
        this.ball.x += this.ball.dx * sm; this.ball.y += this.ball.dy * sm;
        if (this.ball.x <= this.ball.r || this.ball.x >= canvas.width - this.ball.r) { this.ball.dx *= -1; playSound('hit'); }
        if (this.ball.y <= this.ball.r) { this.ball.dy *= -1; playSound('hit'); }
        if (this.ball.y >= canvas.height) { this.gameOver = true; return; }
        if (this.ball.y + this.ball.r >= this.paddle.y - this.paddle.h / 2 && this.ball.x >= this.paddle.x - this.paddle.w / 2 && this.ball.x <= this.paddle.x + this.paddle.w / 2) {
            this.ball.dx = (this.ball.x - this.paddle.x) / (this.paddle.w / 2) * 6; this.ball.dy = -Math.abs(this.ball.dy); playSound('hit');
        }
        for (let i = this.bricks.length - 1; i >= 0; i--) { const b = this.bricks[i];
            if (this.ball.x + this.ball.r > b.x && this.ball.x - this.ball.r < b.x + b.w && this.ball.y + this.ball.r > b.y && this.ball.y - this.ball.r < b.y + b.h) {
                this.bricks.splice(i, 1); this.score += 10 * this.level; playSound('score'); this.ball.dy *= -1; break;
            }
        }
        if (!this.bricks.length) { this.level++; playSound('score'); this.ball = { x: canvas.width / 2, y: canvas.height - 50, r: 8, dx: 4 * (Math.random() > 0.5 ? 1 : -1), dy: -4 - this.level * 0.5 }; this.createBricks(); }
    }
    draw() {
        ctx.fillStyle = '#0a0a1a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        this.bricks.forEach(b => { ctx.fillStyle = b.color; ctx.fillRect(b.x, b.y, b.w, b.h); });
        ctx.fillStyle = '#00ffff'; ctx.beginPath(); ctx.roundRect(this.paddle.x - this.paddle.w / 2, this.paddle.y - this.paddle.h / 2, this.paddle.w, this.paddle.h, 5); ctx.fill();
        ctx.fillStyle = '#ffff00'; ctx.beginPath(); ctx.arc(this.ball.x, this.ball.y, this.ball.r, 0, Math.PI * 2); ctx.fill();
    }
}

// GAME 4: BUBBLE SHOOTER
class BubbleShooter {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false; this.r = 18;
        this.colors = ['#ff0066', '#00ffff', '#ffff00', '#00ff66', '#ff6600'];
        this.shooter = { x: canvas.width / 2, y: canvas.height - 50, angle: -Math.PI / 2, dir: 1 };
        this.current = { color: this.colors[Math.floor(Math.random() * 3)] };
        this.flying = null; this.bubbles = []; this.createBubbles();
    }
    createBubbles() {
        this.bubbles = []; const rows = 4 + Math.floor(this.level / 2), cols = Math.floor(canvas.width / (this.r * 2));
        for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
            const off = r % 2 ? this.r : 0, x = c * this.r * 2 + this.r + off;
            if (x + this.r <= canvas.width) this.bubbles.push({ x, y: r * this.r * 1.7 + this.r + 20, color: this.colors[Math.floor(Math.random() * Math.min(3 + this.level, 5))] });
        }
    }
    update(sm) {
        this.shooter.angle += this.shooter.dir * 0.02 * sm;
        if (this.shooter.angle <= -Math.PI + 0.3) this.shooter.dir = 1;
        else if (this.shooter.angle >= -0.3) this.shooter.dir = -1;
        if ((input.leftPressed || input.rightPressed) && !this.flying) {
            this.flying = { x: this.shooter.x, y: this.shooter.y, dx: Math.cos(this.shooter.angle) * 10, dy: Math.sin(this.shooter.angle) * 10, color: this.current.color };
            playSound('shoot');
        }
        if (this.flying) {
            this.flying.x += this.flying.dx * sm; this.flying.y += this.flying.dy * sm;
            if (this.flying.x <= this.r || this.flying.x >= canvas.width - this.r) { this.flying.dx *= -1; playSound('hit'); }
            if (this.flying.y <= 20 + this.r) this.attach();
            else for (const b of this.bubbles) if (Math.hypot(this.flying.x - b.x, this.flying.y - b.y) < this.r * 1.8) { this.attach(); break; }
        }
        for (const b of this.bubbles) if (b.y + this.r >= this.shooter.y - 30) { this.gameOver = true; return; }
        if (!this.bubbles.length) { this.level++; playSound('score'); this.createBubbles(); }
    }
    attach() {
        const r = Math.round((this.flying.y - 20 - this.r) / (this.r * 1.7)), off = r % 2 ? this.r : 0;
        const c = Math.round((this.flying.x - this.r - off) / (this.r * 2));
        const x = c * this.r * 2 + this.r + off, y = Math.max(r * this.r * 1.7 + this.r + 20, this.r + 20);
        const nb = { x, y, color: this.flying.color }; this.bubbles.push(nb);
        const matches = this.findMatches(nb);
        if (matches.length >= 3) { matches.forEach(m => { const i = this.bubbles.indexOf(m); if (i > -1) this.bubbles.splice(i, 1); });
            this.score += matches.length * 10; playSound('score'); }
        this.flying = null; this.current = { color: this.colors[Math.floor(Math.random() * Math.min(3 + this.level, 5))] };
    }
    findMatches(b, visited = new Set()) {
        const m = [b]; visited.add(b);
        for (const o of this.bubbles) if (!visited.has(o) && o.color === b.color && Math.hypot(b.x - o.x, b.y - o.y) < this.r * 2.2) m.push(...this.findMatches(o, visited));
        return m;
    }
    draw() {
        ctx.fillStyle = '#0a0a1a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.strokeStyle = '#ff0066'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(0, 20); ctx.lineTo(canvas.width, 20); ctx.stroke();
        const bubble = (b,r) => {
            ctx.fillStyle=b.color; ctx.beginPath();ctx.arc(b.x,b.y,r,0,Math.PI*2);ctx.fill();
            ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();
            ctx.fillStyle='#06101c';ctx.font='bold 18px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';
            ctx.fillText(String(this.colors.indexOf(b.color)+1),b.x,b.y);ctx.textBaseline='alphabetic';
        };
        this.bubbles.forEach(b => bubble(b,this.r));
        if (this.flying) bubble(this.flying,this.r);
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 4; ctx.beginPath(); ctx.moveTo(this.shooter.x, this.shooter.y);
        ctx.lineTo(this.shooter.x + Math.cos(this.shooter.angle) * 60, this.shooter.y + Math.sin(this.shooter.angle) * 60); ctx.stroke();
        bubble({x:this.shooter.x,y:this.shooter.y,color:this.current.color},this.r*0.8);
    }
}

// GAME 5: TETRIS
class Tetris {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false; this.gw = 10; this.gh = 20;
        this.cs = Math.min(Math.floor((canvas.width - 40) / this.gw), Math.floor((canvas.height - 40) / this.gh));
        this.ox = (canvas.width - this.gw * this.cs) / 2; this.oy = 20;
        this.grid = Array(this.gh).fill(null).map(() => Array(this.gw).fill(0));
        this.shapes = [[[[1,1,1,1]],'#00ffff'],[[[1,1],[1,1]],'#ffff00'],[[[0,1,0],[1,1,1]],'#ff00ff'],
            [[[1,0],[1,0],[1,1]],'#ff6600'],[[[0,1],[0,1],[1,1]],'#0066ff'],[[[1,1,0],[0,1,1]],'#00ff00'],[[[0,1,1],[1,1,0]],'#ff0066']];
        this.piece = null; this.px = 0; this.py = 0; this.timer = 0; this.interval = 1000; this.lastInput = 0;
        this.moveDir = 1; this.moveTimer = 0;
        this.spawn();
    }
    spawn() {
        const t = this.shapes[Math.floor(Math.random() * this.shapes.length)];
        this.piece = { shape: t[0].map(r => [...r]), color: t[1] };
        this.px = Math.floor((this.gw - this.piece.shape[0].length) / 2); this.py = 0;
        if (this.collides(this.px, this.py, this.piece.shape)) this.gameOver = true;
    }
    rotate(s) { const r = s.length, c = s[0].length, n = []; for (let i = 0; i < c; i++) { n.push([]); for (let j = r - 1; j >= 0; j--) n[i].push(s[j][i]); } return n; }
    collides(x, y, s) {
        for (let r = 0; r < s.length; r++) for (let c = 0; c < s[r].length; c++)
            if (s[r][c] && (x + c < 0 || x + c >= this.gw || y + r >= this.gh || (y + r >= 0 && this.grid[y + r][x + c]))) return true;
        return false;
    }
    lock() {
        for (let r = 0; r < this.piece.shape.length; r++) for (let c = 0; c < this.piece.shape[r].length; c++)
            if (this.piece.shape[r][c] && this.py + r >= 0) this.grid[this.py + r][this.px + c] = this.piece.color;
        let cleared = 0;
        for (let r = this.gh - 1; r >= 0; r--) if (this.grid[r].every(c => c)) { this.grid.splice(r, 1); this.grid.unshift(Array(this.gw).fill(0)); cleared++; r++; }
        if (cleared) { this.score += [0, 100, 300, 500, 800][cleared] * this.level; playSound('score');
            if (this.score >= this.level * 500) { this.level++; this.interval = Math.max(100, 1000 - (this.level - 1) * 100); } }
        this.spawn();
    }
    update(sm) {
        const now = gameNow();
        if (this.switchMode === 1) {
            // 1-switch: auto-move horizontally, press to rotate
            this.moveTimer += 16 * sm;
            if (this.moveTimer >= 400) {
                this.moveTimer = 0;
                if (this.collides(this.px + this.moveDir, this.py, this.piece.shape)) this.moveDir *= -1;
                if (!this.collides(this.px + this.moveDir, this.py, this.piece.shape)) this.px += this.moveDir;
            }
            if (input.leftPressed || input.rightPressed) { 
                const rot = this.rotate(this.piece.shape); 
                if (!this.collides(this.px, this.py, rot)) { this.piece.shape = rot; playSound('move'); } 
            }
        } else {
            // 2-switch: left moves, right rotates
            if (now - this.lastInput > 150) {
                if (input.leftPressed) {
                    // With only move and rotate available, cycling past the left
                    // edge must also make the right-hand columns reachable.
                    const x = this.px > 0 ? this.px - 1 : this.gw - this.piece.shape[0].length;
                    if (!this.collides(x, this.py, this.piece.shape)) { this.px=x;playSound('move'); }
                    this.lastInput=now;
                }
                if (input.rightPressed) { const rot = this.rotate(this.piece.shape); if (!this.collides(this.px, this.py, rot)) { this.piece.shape = rot; playSound('move'); } this.lastInput = now; }
            }
        }
        this.timer += 16 * sm;
        if (this.timer >= this.interval) { this.timer = 0; if (!this.collides(this.px, this.py + 1, this.piece.shape)) this.py++; else this.lock(); }
    }
    draw() {
        ctx.fillStyle = '#0a0a1a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#1a1a2e'; ctx.fillRect(this.ox, this.oy, this.gw * this.cs, this.gh * this.cs);
        for (let r = 0; r < this.gh; r++) for (let c = 0; c < this.gw; c++) if (this.grid[r][c]) { ctx.fillStyle = this.grid[r][c]; ctx.fillRect(this.ox + c * this.cs + 1, this.oy + r * this.cs + 1, this.cs - 2, this.cs - 2); }
        if (this.piece) for (let r = 0; r < this.piece.shape.length; r++) for (let c = 0; c < this.piece.shape[r].length; c++)
            if (this.piece.shape[r][c]) { ctx.fillStyle = this.piece.color; ctx.fillRect(this.ox + (this.px + c) * this.cs + 1, this.oy + (this.py + r) * this.cs + 1, this.cs - 2, this.cs - 2); }
        ctx.strokeStyle = '#ff0066'; ctx.lineWidth = 3; ctx.strokeRect(this.ox, this.oy, this.gw * this.cs, this.gh * this.cs);
    }
}


// GAME 7: PONG
class Pong {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.player = { y: canvas.height / 2, h: 80, speed: 6, dir: 1 };
        this.ai = { y: canvas.height / 2, h: 80, speed: 3 + this.level };
        this.ball = { x: canvas.width / 2, y: canvas.height / 2, r: 10, dx: 5, dy: 3 };
        this.pw = 15; this.aiScore = 0;
    }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: auto-move paddle, press either to change direction
            if (input.leftPressed || input.rightPressed) { this.player.dir *= -1; playSound('move'); }
            this.player.y += this.player.speed * sm * this.player.dir;
            if (this.player.y <= this.player.h / 2) { this.player.y = this.player.h / 2; this.player.dir = 1; }
            if (this.player.y >= canvas.height - this.player.h / 2) { this.player.y = canvas.height - this.player.h / 2; this.player.dir = -1; }
        } else {
            // 2-switch: left=up, right=down
            if (input.left && this.player.y > this.player.h / 2) this.player.y -= this.player.speed * sm;
            if (input.right && this.player.y < canvas.height - this.player.h / 2) this.player.y += this.player.speed * sm;
        }
        if (this.ball.y < this.ai.y) this.ai.y -= this.ai.speed * sm; else if (this.ball.y > this.ai.y) this.ai.y += this.ai.speed * sm;
        this.ai.y = Math.max(this.ai.h / 2, Math.min(canvas.height - this.ai.h / 2, this.ai.y));
        this.ball.x += this.ball.dx * sm; this.ball.y += this.ball.dy * sm;
        if (this.ball.y <= this.ball.r || this.ball.y >= canvas.height - this.ball.r) { this.ball.dy *= -1; playSound('hit'); }
        if (this.ball.x <= 30 + this.ball.r && Math.abs(this.ball.y - this.player.y) < this.player.h / 2) {
            this.ball.dx = Math.abs(this.ball.dx); this.ball.dy = (this.ball.y - this.player.y) / (this.player.h / 2) * 5; playSound('hit');
        }
        if (this.ball.x >= canvas.width - 30 - this.ball.r && Math.abs(this.ball.y - this.ai.y) < this.ai.h / 2) {
            this.ball.dx = -Math.abs(this.ball.dx); this.ball.dy = (this.ball.y - this.ai.y) / (this.ai.h / 2) * 5; playSound('hit');
        }
        if (this.ball.x < 0) { this.aiScore++; if (this.aiScore >= 5) this.gameOver = true; this.resetBall(); }
        if (this.ball.x > canvas.width) { this.score += 10; playSound('score'); if (this.score % 50 === 0) { this.level++; this.ai.speed++; } this.resetBall(); }
    }
    resetBall() { this.ball = { x: canvas.width / 2, y: canvas.height / 2, r: 10, dx: 5 * (Math.random() > 0.5 ? 1 : -1), dy: (Math.random() - 0.5) * 6 }; }
    draw() {
        ctx.fillStyle = '#0a0a1a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.setLineDash([10, 10]); ctx.strokeStyle = 'rgba(255,255,255,0.3)'; ctx.beginPath(); ctx.moveTo(canvas.width / 2, 0); ctx.lineTo(canvas.width / 2, canvas.height); ctx.stroke(); ctx.setLineDash([]);
        ctx.fillStyle = '#00ffff'; ctx.fillRect(15, this.player.y - this.player.h / 2, this.pw, this.player.h);
        ctx.fillStyle = '#ff0066'; ctx.fillRect(canvas.width - 15 - this.pw, this.ai.y - this.ai.h / 2, this.pw, this.ai.h);
        ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(this.ball.x, this.ball.y, this.ball.r, 0, Math.PI * 2); ctx.fill();
        ctx.font = '20px system-ui'; ctx.fillStyle = '#fff'; ctx.textAlign = 'center';
        ctx.fillText(Math.floor(this.score / 10), canvas.width / 4, 40); ctx.fillText(this.aiScore, canvas.width * 3 / 4, 40);
    }
}

// GAME 8: FLAPPY BIRD
class Flappy {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.bird = { x: canvas.width * 0.3, y: canvas.height / 2, vy: 0, r: 15 };
        this.pipes = []; this.pipeTimer = 0; this.gravity = 0.22; this.jumpForce = -5;
    }
    update(sm) {
        if (input.leftPressed || input.rightPressed) { this.bird.vy = this.jumpForce; playSound('jump'); }
        this.bird.vy += this.gravity * sm; this.bird.y += this.bird.vy * sm;
        if (this.bird.y < 0 || this.bird.y > canvas.height) { this.gameOver = true; return; }
        this.pipeTimer += 16 * sm;
        if (this.pipeTimer > 1800 / (1 + this.level * 0.1)) {
            this.pipeTimer = 0; const gap = Math.max(100, 150 - this.level * 5), gapY = Math.random() * (canvas.height - gap - 100) + 50;
            this.pipes.push({ x: canvas.width, gapY, gap, w: 60, passed: false });
        }
        this.pipes = this.pipes.filter(p => {
            p.x -= 1.8 * sm * (1 + this.level * 0.08);
            if (this.bird.x + this.bird.r > p.x && this.bird.x - this.bird.r < p.x + p.w) {
                if (this.bird.y - this.bird.r < p.gapY || this.bird.y + this.bird.r > p.gapY + p.gap) this.gameOver = true;
            }
            if (!p.passed && p.x + p.w < this.bird.x) { p.passed = true; this.score += 10; playSound('score'); if (this.score % 50 === 0) this.level++; }
            return p.x > -p.w;
        });
    }
    draw() {
        ctx.fillStyle = '#87CEEB'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        this.pipes.forEach(p => { ctx.fillStyle = '#00aa00';
            ctx.fillRect(p.x, 0, p.w, p.gapY); ctx.fillRect(p.x, p.gapY + p.gap, p.w, canvas.height - p.gapY - p.gap);
            ctx.fillStyle = '#00cc00'; ctx.fillRect(p.x - 5, p.gapY - 20, p.w + 10, 20); ctx.fillRect(p.x - 5, p.gapY + p.gap, p.w + 10, 20);
        });
        ctx.fillStyle = '#ffff00'; ctx.beginPath(); ctx.arc(this.bird.x, this.bird.y, this.bird.r, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ff6600'; ctx.beginPath(); ctx.moveTo(this.bird.x + this.bird.r, this.bird.y);
        ctx.lineTo(this.bird.x + this.bird.r + 10, this.bird.y - 3); ctx.lineTo(this.bird.x + this.bird.r + 10, this.bird.y + 3); ctx.fill();
        ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(this.bird.x + 5, this.bird.y - 3, 3, 0, Math.PI * 2); ctx.fill();
    }
}


// SOURCE: games2.js
// GAME 9: DINO RUNNER
class Dino {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.ground = canvas.height - 35;
        this.dino = { x: 80, y: this.ground, w: 40, h: 50, vy: 0, ducking: false };
        this.obstacles = []; this.timer = 0; this.speed = 6; this.jumping = false;
    }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: press either button to jump (no ducking)
            if ((input.leftPressed || input.rightPressed) && !this.jumping && this.dino.y >= this.ground) { this.dino.vy = -15; this.jumping = true; playSound('jump'); }
            this.dino.ducking = false;
        } else {
            // 2-switch: left=jump, right=duck
            if (input.leftPressed && !this.jumping && this.dino.y >= this.ground) { this.dino.vy = -15; this.jumping = true; playSound('jump'); }
            if (input.right) this.dino.ducking = true; else this.dino.ducking = false;
        }
        this.dino.vy += 0.8 * sm; this.dino.y += this.dino.vy * sm;
        if (this.dino.y >= this.ground) { this.dino.y = this.ground; this.dino.vy = 0; this.jumping = false; }
        const h = this.dino.ducking ? 25 : 50;
        this.timer += 16 * sm;
        if (this.timer > 1500 / (1 + this.level * 0.1)) {
            this.timer = 0;
            const type = this.switchMode === 1 ? 'cactus' : (Math.random() > 0.7 ? 'bird' : 'cactus'); // No birds in 1-switch mode
            if (type === 'cactus') this.obstacles.push({ x: canvas.width, y: this.ground, w: 20, h: 40, type });
            else this.obstacles.push({ x: canvas.width, y: this.ground - 30, w: 30, h: 20, type });
        }
        this.obstacles = this.obstacles.filter(o => {
            o.x -= this.speed * sm * (1 + this.level * 0.1);
            if (o.x < this.dino.x + this.dino.w && o.x + o.w > this.dino.x &&
                this.dino.y > o.y - o.h && this.dino.y - h < o.y) this.gameOver = true;
            return o.x > -50;
        });
        this.score++; if (this.score % 500 === 0) { this.level++; playSound('score'); }
    }
    draw() {
        ctx.fillStyle = '#f7f7f7'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#555'; ctx.fillRect(0, this.ground, canvas.width, 5);
        const h = this.dino.ducking ? 25 : 50;
        ctx.fillStyle = '#555'; ctx.fillRect(this.dino.x, this.dino.y - h, this.dino.w, h);
        ctx.fillStyle = '#333'; ctx.fillRect(this.dino.x + 25, this.dino.y - h, 20, 20);
        ctx.fillStyle = '#fff'; ctx.fillRect(this.dino.x + 35, this.dino.y - h + 3, 5, 5);
        this.obstacles.forEach(o => {
            if (o.type === 'cactus') { ctx.fillStyle = '#228B22'; ctx.fillRect(o.x, o.y - o.h, o.w, o.h); }
            else { ctx.fillStyle = '#666'; ctx.beginPath(); ctx.ellipse(o.x + o.w / 2, o.y - o.h / 2, o.w / 2, o.h / 2, 0, 0, Math.PI * 2); ctx.fill(); }
        });
    }
}

// GAME 10: HELICOPTER
class Helicopter {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.heli = { x: 100, y: canvas.height / 2, vy: 0, w: 50, h: 25 };
        this.walls = []; this.gap = 200; this.timer = 0; this.ceilY = 50; this.floorY = canvas.height - 50;
    }
    update(sm) {
        // Both modes work the same - any button thrusts up
        if (input.left || input.right) this.heli.vy -= 0.5 * sm; else this.heli.vy += 0.28 * sm;
        this.heli.vy = Math.max(-5, Math.min(5, this.heli.vy));
        this.heli.y += this.heli.vy * sm;
        if (this.heli.y < this.ceilY || this.heli.y + this.heli.h > this.floorY) { this.gameOver = true; return; }
        this.timer += 16 * sm;
        if (this.timer > 800) {
            this.timer = 0;
            const h = Math.random() * (this.floorY - this.ceilY - this.gap - 50) + 25;
            this.walls.push({ x: canvas.width, y: this.ceilY, h, bottom: false });
            this.walls.push({ x: canvas.width, y: this.ceilY + h + this.gap, h: this.floorY - this.ceilY - h - this.gap, bottom: true });
        }
        this.walls = this.walls.filter(w => {
            w.x -= 2.5 * sm * (1 + this.level * 0.08);
            if (this.heli.x + this.heli.w > w.x && this.heli.x < w.x + 30) {
                if (!w.bottom && this.heli.y < w.y + w.h) this.gameOver = true;
                if (w.bottom && this.heli.y + this.heli.h > w.y) this.gameOver = true;
            }
            return w.x > -30;
        });
        this.score++; if (this.score % 500 === 0) { this.level++; this.gap = Math.max(100, this.gap - 10); playSound('score'); }
    }
    draw() {
        ctx.fillStyle = '#1a1a2e'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#2a2a3a'; ctx.fillRect(0, 0, canvas.width, this.ceilY); ctx.fillRect(0, this.floorY, canvas.width, canvas.height - this.floorY);
        ctx.fillStyle = '#ff0066'; this.walls.forEach(w => ctx.fillRect(w.x, w.y, 30, w.h));
        // Helicopter body
        const hx = this.heli.x, hy = this.heli.y, hw = this.heli.w, hh = this.heli.h;
        // Main fuselage
        ctx.fillStyle = '#00aacc';
        ctx.beginPath(); ctx.roundRect(hx, hy, hw, hh, 5); ctx.fill();
        // Cockpit bubble
        ctx.fillStyle = '#66ddff';
        ctx.beginPath(); ctx.ellipse(hx + hw * 0.25, hy + hh * 0.45, hw * 0.22, hh * 0.4, 0, 0, Math.PI * 2); ctx.fill();
        // Tail boom
        ctx.fillStyle = '#0088aa';
        ctx.fillRect(hx + hw - 5, hy + hh * 0.3, hw * 0.35, hh * 0.2);
        // Tail rotor
        ctx.fillStyle = '#aaa';
        ctx.fillRect(hx + hw + hw * 0.35 - 2, hy - 6, 4, hh + 12);
        // Main rotor blade (animated by using heli.x as seed)
        const rotAngle = (typeof settings !== 'undefined' && settings.reducedMotion) ? 0 : (gameNow() * 0.01) % (Math.PI * 2);
        ctx.strokeStyle = '#888'; ctx.lineWidth = 4; ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(hx + hw * 0.45 + Math.cos(rotAngle) * 40, hy - 3 + Math.sin(rotAngle) * 4);
        ctx.lineTo(hx + hw * 0.45 - Math.cos(rotAngle) * 40, hy - 3 - Math.sin(rotAngle) * 4);
        ctx.stroke();
        // Landing skids
        ctx.strokeStyle = '#666'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(hx + 5, hy + hh); ctx.lineTo(hx + 5, hy + hh + 8); ctx.lineTo(hx + hw * 0.5, hy + hh + 8); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(hx + hw - 5, hy + hh); ctx.lineTo(hx + hw - 5, hy + hh + 8); ctx.lineTo(hx + hw * 0.5, hy + hh + 8); ctx.stroke();
    }
}

// GAME 11: RHYTHM
class Rhythm {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.notes = []; this.timer = 0; this.hitY = canvas.height - 80; this.combo = 0; this.misses = 0;
    }
    update(sm) {
        this.timer += 16 * sm;
        if (this.timer > 600 / (1 + this.level * 0.1)) {
            this.timer = 0;
            const lane = this.switchMode === 1 ? 0 : (Math.random() > 0.5 ? 0 : 1);
            this.notes.push({ lane, y: -30, hit: false });
        }
        this.notes = this.notes.filter(n => {
            n.y += 5 * sm * (1 + this.level * 0.2);
            if (n.y > this.hitY + 50 && !n.hit) { this.misses++; this.combo = 0; if (this.misses >= 10) this.gameOver = true; return false; }
            return n.y < canvas.height + 30;
        });
        const hitWindow = 40;
        if (this.switchMode === 1) {
            // 1-switch: either button hits any note
            if (input.leftPressed || input.rightPressed) {
                const hit = this.notes.find(n => !n.hit && Math.abs(n.y - this.hitY) < hitWindow);
                if (hit) { hit.hit = true; this.score += 10 * (1 + Math.floor(this.combo / 10)); this.combo++; playSound('score'); }
                else { playSound('low'); this.combo = 0; }
            }
        } else {
            // 2-switch: match button to lane
            if (input.leftPressed) {
                const hit = this.notes.find(n => n.lane === 0 && !n.hit && Math.abs(n.y - this.hitY) < hitWindow);
                if (hit) { hit.hit = true; this.score += 10 * (1 + Math.floor(this.combo / 10)); this.combo++; playSound('score'); }
                else { playSound('low'); this.combo = 0; }
            }
            if (input.rightPressed) {
                const hit = this.notes.find(n => n.lane === 1 && !n.hit && Math.abs(n.y - this.hitY) < hitWindow);
                if (hit) { hit.hit = true; this.score += 10 * (1 + Math.floor(this.combo / 10)); this.combo++; playSound('score'); }
                else { playSound('low'); this.combo = 0; }
            }
        }
        if (this.score > this.level * 200) this.level++;
    }
    draw() {
        ctx.fillStyle = '#0a0a1a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        const lw = canvas.width / 4;
        if (this.switchMode === 1) {
            // Single center lane for 1-switch
            const lx = canvas.width / 2 - lw / 2;
            ctx.fillStyle = '#1a1a3a'; ctx.fillRect(lx, 0, lw, canvas.height);
            ctx.fillStyle = 'rgba(255,0,102,0.3)'; ctx.fillRect(lx, this.hitY - 20, lw, 40);
            this.notes.forEach(n => {
                if (n.hit) return;
                ctx.fillStyle = '#ff0066';
                ctx.beginPath(); ctx.arc(canvas.width / 2, n.y, 25, 0, Math.PI * 2); ctx.fill();
            });
        } else {
            // Two lanes for 2-switch
            const lx1 = canvas.width / 2 - lw - 20, lx2 = canvas.width / 2 + 20;
            ctx.fillStyle = '#1a1a3a'; ctx.fillRect(lx1, 0, lw, canvas.height); ctx.fillRect(lx2, 0, lw, canvas.height);
            ctx.fillStyle = 'rgba(255,0,102,0.3)'; ctx.fillRect(lx1, this.hitY - 20, lw, 40); ctx.fillRect(lx2, this.hitY - 20, lw, 40);
            this.notes.forEach(n => {
                if (n.hit) return;
                ctx.fillStyle = n.lane === 0 ? '#ff0066' : '#00ffff';
                const x = n.lane === 0 ? lx1 + lw / 2 : lx2 + lw / 2;
                ctx.beginPath(); ctx.arc(x, n.y, 25, 0, Math.PI * 2); ctx.fill();
            });
        }
        ctx.fillStyle = '#fff'; ctx.font = '16px system-ui'; ctx.textAlign = 'center';
        ctx.fillText(`${ui("combo")}: ${this.combo}`, canvas.width / 2, 40);
    }
}

// GAME 12: TANK BATTLE
class Tank {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.tank = { x: canvas.width / 2, y: canvas.height / 2, angle: -Math.PI / 2, w: 40, h: 30, rotDir: 1 };
        this.bullets = []; this.enemies = []; this.lastShot = 0; this.enemyTimer = 0;
    }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: auto-rotate, press to change direction
            if (input.leftPressed || input.rightPressed) { this.tank.rotDir *= -1; playSound('move'); }
            this.tank.angle += 0.03 * sm * this.tank.rotDir;
        } else {
            // 2-switch: normal left/right rotation
            if (input.left) this.tank.angle -= 0.05 * sm;
            if (input.right) this.tank.angle += 0.05 * sm;
        }
        if (gameNow() - this.lastShot > 300) {
            this.bullets.push({ x: this.tank.x + Math.cos(this.tank.angle) * 25, y: this.tank.y + Math.sin(this.tank.angle) * 25,
                dx: Math.cos(this.tank.angle) * 8, dy: Math.sin(this.tank.angle) * 8 });
            playSound('shoot'); this.lastShot = gameNow();
        }
        this.bullets = this.bullets.filter(b => { b.x += b.dx * sm; b.y += b.dy * sm;
            return b.x > 0 && b.x < canvas.width && b.y > 0 && b.y < canvas.height; });
        this.enemyTimer += 16 * sm;
        if (this.enemyTimer > 2000 / (1 + this.level * 0.2)) {
            this.enemyTimer = 0;
            const side = Math.floor(Math.random() * 4);
            let x, y;
            if (side === 0) { x = Math.random() * canvas.width; y = -20; }
            else if (side === 1) { x = canvas.width + 20; y = Math.random() * canvas.height; }
            else if (side === 2) { x = Math.random() * canvas.width; y = canvas.height + 20; }
            else { x = -20; y = Math.random() * canvas.height; }
            this.enemies.push({ x, y, r: 20 });
        }
        this.enemies = this.enemies.filter(e => {
            const dx = this.tank.x - e.x, dy = this.tank.y - e.y, dist = Math.hypot(dx, dy);
            e.x += (dx / dist) * 2 * sm * (1 + this.level * 0.1);
            e.y += (dy / dist) * 2 * sm * (1 + this.level * 0.1);
            if (dist < 30) { this.gameOver = true; return false; }
            for (let i = this.bullets.length - 1; i >= 0; i--) {
                if (Math.hypot(this.bullets[i].x - e.x, this.bullets[i].y - e.y) < e.r + 5) {
                    this.bullets.splice(i, 1); this.score += 10 * this.level; playSound('hit');
                    if (this.score % 100 === 0) this.level++;
                    return false;
                }
            }
            return true;
        });
    }
    draw() {
        // Lighter background for better contrast
        ctx.fillStyle = '#2d5a2d'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        // Subtle terrain texture
        ctx.fillStyle = 'rgba(0,0,0,0.15)';
        for (let i = 0; i < 8; i++) ctx.fillRect((i * 137) % canvas.width, (i * 113) % canvas.height, 40, 25);

        // Draw tank
        ctx.save(); ctx.translate(this.tank.x, this.tank.y); ctx.rotate(this.tank.angle);
        // Treads
        ctx.fillStyle = '#222'; ctx.fillRect(-24, -18, 48, 8); ctx.fillRect(-24, 10, 48, 8);
        ctx.fillStyle = '#333';
        for (let i = -22; i < 22; i += 8) { ctx.fillRect(i, -18, 6, 8); ctx.fillRect(i, 10, 6, 8); }
        // Hull
        ctx.fillStyle = '#6a8a3a'; ctx.fillRect(-18, -12, 36, 24);
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.strokeRect(-18, -12, 36, 24);
        ctx.fillStyle = '#5a7a2a'; ctx.fillRect(-16, -10, 32, 20);
        // Turret
        ctx.fillStyle = '#7a9a45'; ctx.beginPath(); ctx.ellipse(0, 0, 14, 12, 0, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#6a8a35'; ctx.beginPath(); ctx.ellipse(0, 0, 10, 8, 0, 0, Math.PI * 2); ctx.fill();
        // Barrel
        ctx.fillStyle = '#4a5f20'; ctx.fillRect(10, -3, 22, 6); ctx.fillRect(28, -2, 5, 4);
        // Hatch
        ctx.fillStyle = '#5a7a30'; ctx.beginPath(); ctx.ellipse(-3, -2, 5, 4, 0, 0, Math.PI * 2); ctx.fill();
        ctx.restore();

        // Bullets
        ctx.fillStyle = '#ffff00'; this.bullets.forEach(b => {
            ctx.beginPath(); ctx.arc(b.x, b.y, 4, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = 'rgba(255,200,0,0.4)'; ctx.beginPath(); ctx.arc(b.x, b.y, 7, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = '#ffff00';
        });

        // Enemies — draw as enemy tanks
        this.enemies.forEach(e => {
            const s = e.r / 20; // scale
            ctx.save(); ctx.translate(e.x, e.y);
            // Enemy tank body (red tones)
            ctx.fillStyle = '#882222'; ctx.fillRect(-e.r * 0.8, -e.r * 0.5, e.r * 1.6, e.r);
            ctx.fillStyle = '#aa3333'; ctx.fillRect(-e.r * 0.65, -e.r * 0.4, e.r * 1.3, e.r * 0.8);
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.strokeRect(-e.r * 0.8, -e.r * 0.5, e.r * 1.6, e.r);
            // Turret
            ctx.fillStyle = '#cc4444'; ctx.beginPath(); ctx.ellipse(0, 0, e.r * 0.5, e.r * 0.4, 0, 0, Math.PI * 2); ctx.fill();
            // Aim towards player
            const ang = Math.atan2(this.tank.y - e.y, this.tank.x - e.x);
            ctx.fillStyle = '#993333'; ctx.save(); ctx.rotate(ang);
            ctx.fillRect(e.r * 0.3, -e.r * 0.08, e.r * 0.6, e.r * 0.16);
            ctx.restore();
            // Treads
            ctx.fillStyle = '#551111'; ctx.fillRect(-e.r * 0.8, -e.r * 0.5, e.r * 1.6, e.r * 0.2);
            ctx.fillRect(-e.r * 0.8, e.r * 0.3, e.r * 1.6, e.r * 0.2);
            ctx.restore();
        });
    }
}

// GAME 13: ASTEROIDS
class Asteroids {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.ship = { x: canvas.width / 2, y: canvas.height / 2, angle: -Math.PI / 2, rotDir: 1 };
        this.bullets = []; this.asteroids = []; this.lastShot = 0;
        for (let i = 0; i < 2 + this.level; i++) this.spawnAsteroid();
    }
    spawnAsteroid(x, y, size) {
        size = size || 40;
        if (!x) { const side = Math.floor(Math.random() * 4);
            if (side === 0) { x = Math.random() * canvas.width; y = -size; }
            else if (side === 1) { x = canvas.width + size; y = Math.random() * canvas.height; }
            else if (side === 2) { x = Math.random() * canvas.width; y = canvas.height + size; }
            else { x = -size; y = Math.random() * canvas.height; }
        }
        const angle = Math.random() * Math.PI * 2;
        this.asteroids.push({ x, y, dx: Math.cos(angle) * (0.8 + Math.random() * 1.2), dy: Math.sin(angle) * (0.8 + Math.random() * 1.2), r: size });
    }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: auto-rotate, press to change direction
            if (input.leftPressed || input.rightPressed) { this.ship.rotDir *= -1; playSound('move'); }
            this.ship.angle += 0.05 * sm * this.ship.rotDir;
        } else {
            // 2-switch: normal left/right rotation
            if (input.left) this.ship.angle -= 0.08 * sm;
            if (input.right) this.ship.angle += 0.08 * sm;
        }
        if (gameNow() - this.lastShot > 550) {
            this.bullets.push({ x: this.ship.x + Math.cos(this.ship.angle) * 15, y: this.ship.y + Math.sin(this.ship.angle) * 15,
                dx: Math.cos(this.ship.angle) * 10, dy: Math.sin(this.ship.angle) * 10 });
            playSound('shoot'); this.lastShot = gameNow();
        }
        this.bullets = this.bullets.filter(b => { b.x += b.dx * sm; b.y += b.dy * sm;
            return b.x > -10 && b.x < canvas.width + 10 && b.y > -10 && b.y < canvas.height + 10; });
        this.asteroids.forEach(a => { a.x += a.dx * sm; a.y += a.dy * sm;
            if (a.x < -a.r) a.x = canvas.width + a.r; if (a.x > canvas.width + a.r) a.x = -a.r;
            if (a.y < -a.r) a.y = canvas.height + a.r; if (a.y > canvas.height + a.r) a.y = -a.r;
        });
        for (let i = this.asteroids.length - 1; i >= 0; i--) {
            const a = this.asteroids[i];
            if (Math.hypot(this.ship.x - a.x, this.ship.y - a.y) < a.r + 10) { this.gameOver = true; return; }
            for (let j = this.bullets.length - 1; j >= 0; j--) {
                if (Math.hypot(this.bullets[j].x - a.x, this.bullets[j].y - a.y) < a.r + 3) {
                    this.bullets.splice(j, 1);
                    if (a.r > 15) { this.spawnAsteroid(a.x, a.y, a.r / 2); this.spawnAsteroid(a.x, a.y, a.r / 2); }
                    this.asteroids.splice(i, 1);
                    this.score += Math.floor(50 / a.r * 10) * this.level; playSound('hit');
                    break;
                }
            }
        }
        if (!this.asteroids.length) { this.level++; playSound('score'); for (let i = 0; i < 2 + this.level; i++) this.spawnAsteroid(); }
    }
    draw() {
        ctx.fillStyle = '#000'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        for (let i = 0; i < 30; i++) { ctx.fillStyle = '#fff'; ctx.fillRect((i * 73) % canvas.width, (i * 97) % canvas.height, 1, 1); }
        ctx.save(); ctx.translate(this.ship.x, this.ship.y); ctx.rotate(this.ship.angle);
        ctx.strokeStyle = '#00ffff'; ctx.lineWidth = 2; ctx.beginPath();
        ctx.moveTo(15, 0); ctx.lineTo(-10, -10); ctx.lineTo(-5, 0); ctx.lineTo(-10, 10); ctx.closePath(); ctx.stroke();
        ctx.restore();
        ctx.fillStyle = '#ffff00'; this.bullets.forEach(b => { ctx.beginPath(); ctx.arc(b.x, b.y, 3, 0, Math.PI * 2); ctx.fill(); });
        ctx.strokeStyle = '#888'; ctx.lineWidth = 2;
        this.asteroids.forEach(a => { ctx.beginPath(); ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2); ctx.stroke(); });
    }
}

// GAME 14: SKIING
class Skiing {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.skier = { x: canvas.width / 2, speed: 5, dir: 1 };
        this.gates = []; this.trees = []; this.timer = 0; this.scroll = 0;
    }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: auto-move, press to change direction
            if (input.leftPressed || input.rightPressed) { this.skier.dir *= -1; playSound('move'); }
            this.skier.x += this.skier.speed * sm * this.skier.dir;
        } else {
            // 2-switch: normal left/right
            if (input.left) this.skier.x -= this.skier.speed * sm;
            if (input.right) this.skier.x += this.skier.speed * sm;
        }
        this.skier.x = Math.max(20, Math.min(canvas.width - 20, this.skier.x));
        const scrollSpeed = 5 * sm * (1 + this.level * 0.2);
        this.scroll += scrollSpeed;
        this.timer += 16 * sm;
        if (this.timer > 1000) {
            this.timer = 0;
            if (Math.random() > 0.3) {
                const gx = Math.random() * (canvas.width - 150) + 50;
                this.gates.push({ x: gx, y: -30, w: 100, passed: false });
            }
            for (let i = 0; i < 2; i++) this.trees.push({ x: Math.random() * canvas.width, y: -30 });
        }
        this.gates = this.gates.filter(g => {
            g.y += scrollSpeed;
            if (g.y > 80 && g.y < 120 && !g.passed) {
                if (this.skier.x > g.x && this.skier.x < g.x + g.w) { this.score += 10 * this.level; g.passed = true; playSound('score'); }
                else { this.score -= 5; g.passed = true; playSound('low'); }
            }
            return g.y < canvas.height + 30;
        });
        this.trees = this.trees.filter(t => {
            t.y += scrollSpeed;
            if (Math.abs(t.x - this.skier.x) < 15 && t.y > 70 && t.y < 110) this.gameOver = true;
            return t.y < canvas.height + 30;
        });
        if (this.scroll > this.level * 2000) { this.level++; playSound('score'); }
    }
    draw() {
        ctx.fillStyle = '#f0f8ff'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        this.gates.forEach(g => { ctx.fillStyle = '#ff0000'; ctx.fillRect(g.x, g.y, 5, 30); ctx.fillRect(g.x + g.w - 5, g.y, 5, 30);
            ctx.strokeStyle = '#ff0000'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(g.x, g.y); ctx.lineTo(g.x + g.w, g.y); ctx.stroke(); });
        this.trees.forEach(t => { ctx.fillStyle = '#228B22'; ctx.beginPath(); ctx.moveTo(t.x, t.y); ctx.lineTo(t.x - 15, t.y + 30); ctx.lineTo(t.x + 15, t.y + 30); ctx.fill();
            ctx.fillStyle = '#8B4513'; ctx.fillRect(t.x - 3, t.y + 30, 6, 10); });
        const sx = this.skier.x, sy = 90;
        // Head (helmet)
        ctx.fillStyle = '#0055cc'; ctx.beginPath(); ctx.arc(sx, sy - 22, 10, 0, Math.PI * 2); ctx.fill();
        // Face
        ctx.fillStyle = '#ffcc88'; ctx.beginPath(); ctx.arc(sx, sy - 14, 7, 0, Math.PI * 2); ctx.fill();
        // Body (ski suit)
        ctx.fillStyle = '#0055cc'; ctx.fillRect(sx - 7, sy - 8, 14, 20);
        // Poles (angled backward)
        ctx.strokeStyle = '#888'; ctx.lineWidth = 2; ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(sx - 7, sy); ctx.lineTo(sx - 20, sy + 18); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(sx + 7, sy); ctx.lineTo(sx + 20, sy + 18); ctx.stroke();
        // Pole circles
        ctx.fillStyle = '#aaa'; ctx.beginPath(); ctx.arc(sx - 20, sy + 18, 3, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(sx + 20, sy + 18, 3, 0, Math.PI * 2); ctx.fill();
        // Skis
        ctx.fillStyle = '#222'; ctx.lineWidth = 4; ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(sx - 18, sy + 12); ctx.lineTo(sx + 2, sy + 14); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(sx - 2, sy + 14); ctx.lineTo(sx + 18, sy + 12); ctx.stroke();
    }
}


// SOURCE: games3.js
// GAME 17: BALANCE
class Balance {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.platform = { angle: 0, angVel: 0, tiltDir: 1 };
        this.ball = { x: canvas.width / 2, vx: 0 };
        this.timer = 0;
    }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: auto-tilt, press to change direction
            if (input.leftPressed || input.rightPressed) { this.platform.tiltDir *= -1; playSound('move'); }
            this.platform.angVel += 0.002 * sm * this.platform.tiltDir;
        } else {
            // 2-switch: normal left/right tilt
            if (input.left) this.platform.angVel -= 0.003 * sm;
            if (input.right) this.platform.angVel += 0.003 * sm;
        }
        this.platform.angVel *= 0.98;
        this.platform.angle += this.platform.angVel * sm;
        this.platform.angle = Math.max(-0.5, Math.min(0.5, this.platform.angle));
        this.ball.vx += Math.sin(this.platform.angle) * 0.12 * sm * (1 + this.level * 0.08);
        this.ball.vx *= 0.99;
        this.ball.x += this.ball.vx * sm;
        const platW = Math.max(140, 300 - this.level * 10);
        const minX = canvas.width / 2 - platW / 2 + 15;
        const maxX = canvas.width / 2 + platW / 2 - 15;
        if (this.ball.x < minX || this.ball.x > maxX) this.gameOver = true;
        this.timer += 16 * sm;
        this.score = Math.floor(this.timer / 100);
        if (this.timer > this.level * 5000) { this.level++; playSound('score'); }
        // Auto-nudge: after 4 seconds of stability, add a small random perturbation
        if (this.timer > 0 && this.timer % 4000 < 16 * sm + 1) {
            this.platform.angVel += (Math.random() - 0.5) * 0.012;
        }
    }
    draw() {
        ctx.fillStyle = '#1a1a2e'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        const platW = Math.max(140, 300 - this.level * 10), platH = 15, platY = canvas.height / 2 + 50;
        ctx.save(); ctx.translate(canvas.width / 2, platY); ctx.rotate(this.platform.angle);
        ctx.fillStyle = '#8B4513'; ctx.fillRect(-platW / 2, -platH / 2, platW, platH);
        ctx.restore();
        ctx.fillStyle = '#654321'; ctx.fillRect(canvas.width / 2 - 10, platY, 20, canvas.height / 2 - 50);
        const ballY = platY - platH / 2 - 20 + Math.sin(this.platform.angle) * (this.ball.x - canvas.width / 2);
        ctx.fillStyle = '#ff0066'; ctx.beginPath(); ctx.arc(this.ball.x, ballY, 20, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#fff'; ctx.font = '16px system-ui'; ctx.textAlign = 'center';
        ctx.fillText(`${ui("time")}: ${Math.floor(this.timer / 1000)}s`, canvas.width / 2, 40);
    }
}

// GAME 18: SIMON SAYS
class Simon {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.sequence = []; this.playerSeq = []; this.showingSeq = false;
        this.showIndex = 0; this.showTimer = 0; this.inputEnabled = false;
        this.flash = null; this.flashTimer = 0; this.answerScan = 0; this.answerTimer = 0; this.nextRoundTimer = 0;
        this.addToSequence();
    }
    addToSequence() {
        this.sequence.push(Math.random() > 0.5 ? 0 : 1);
        this.playerSeq = []; this.showingSeq = true; this.showIndex = 0; this.showTimer = 0; this.inputEnabled = false;
    }
    update(sm) {
        if (this.nextRoundTimer > 0) {
            this.nextRoundTimer -= 16 * sm;
            if (this.nextRoundTimer <= 0) this.addToSequence();
            return;
        }
        if (this.flash !== null) {
            this.flashTimer += 16 * sm;
            if (this.flashTimer > 650) { this.flash = null; this.flashTimer = 0; }
        }
        if (this.showingSeq) {
            this.showTimer += 16 * sm;
            if (this.showTimer > 1200) {
                this.showTimer = 0;
                if (this.showIndex < this.sequence.length) {
                    this.flash = this.sequence[this.showIndex];
                    this.flashTimer = 0;
                    if (this.flash === 0) playSound('low'); else playSound('high');
                    this.showIndex++;
                } else { this.showingSeq = false; this.inputEnabled = true; this.answerScan = 0; this.answerTimer = 0; }
            }
        }
        if (this.inputEnabled) {
            if (this.switchMode === 1) {
                this.answerTimer += 16 * sm;
                const interval = typeof settings === 'undefined' ? 1500 : settings.scanSpeed;
                if (this.answerTimer >= interval) { this.answerTimer = 0; this.answerScan = 1 - this.answerScan; }
                if (input.leftPressed || input.rightPressed) {
                    this.playerSeq.push(this.answerScan); this.flash = this.answerScan; this.flashTimer = 0; this.checkInput();
                }
                return;
            }
            if (input.leftPressed) { this.playerSeq.push(0); this.flash = 0; this.flashTimer = 0; playSound('low'); this.checkInput(); }
            if (input.rightPressed && this.inputEnabled && !this.gameOver) { this.playerSeq.push(1); this.flash = 1; this.flashTimer = 0; playSound('high'); this.checkInput(); }
        }
    }
    checkInput() {
        const i = this.playerSeq.length - 1;
        if (this.playerSeq[i] !== this.sequence[i]) { this.gameOver = true; return; }
        if (this.playerSeq.length === this.sequence.length) {
            this.score += 10 * this.level; this.level = this.sequence.length;
            playSound('score');
            this.nextRoundTimer = 800;
            this.inputEnabled = false;
        }
    }
    draw() {
        ctx.fillStyle = '#1a1a2e'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        const bw = 120, bh = 120, gap = 40;
        const lx = canvas.width / 2 - bw - gap / 2, rx = canvas.width / 2 + gap / 2, by = canvas.height / 2 - bh / 2;
        ctx.fillStyle = this.flash === 0 ? '#ff6666' : '#ff0066';
        ctx.beginPath(); ctx.roundRect(lx, by, bw, bh, 20); ctx.fill();
        ctx.fillStyle = this.flash === 1 ? '#66ffff' : '#00ffff';
        ctx.beginPath(); ctx.roundRect(rx, by, bw, bh, 20); ctx.fill();
        ctx.fillStyle = '#fff'; ctx.font = '16px system-ui'; ctx.textAlign = 'center';
        if (this.showingSeq) {
            ctx.fillText(ui('watch'), canvas.width / 2, 60);
            // Highlight which button is being shown
            if (this.flash !== null) {
                const arrowX = this.flash === 0 ? lx + bw / 2 : rx + bw / 2;
                ctx.font = '28px Arial'; ctx.fillText('▼', arrowX, by - 10);
            }
        } else if (this.inputEnabled) {
            ctx.fillText(ui('yourTurn'), canvas.width / 2, 60);
            // Show which button to press next
            if (this.playerSeq.length < this.sequence.length) {
                const next = this.switchMode === 1 ? this.answerScan : this.sequence[this.playerSeq.length];
                const arrowX = next === 0 ? lx + bw / 2 : rx + bw / 2;
                const arrowLabel = next === 0 ? ui('left') : ui('right');
                ctx.fillStyle = '#ffff00'; ctx.font = '28px Arial'; ctx.fillText('▼', arrowX, by - 10);
                ctx.font = '16px system-ui'; ctx.fillText(`${ui("action")} ${arrowLabel}`, arrowX, by - 35);
            }
        }
        ctx.fillStyle = '#fff'; ctx.font = '16px system-ui';
        ctx.fillText(`${ui("round")}: ${this.sequence.length}`, canvas.width / 2, canvas.height - 40);
    }
}

// GAME 19: WHACK-A-MOLE
class Whack {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.moles = [{ side: 0, up: false, timer: 0 }, { side: 1, up: false, timer: 0 }];
        this.spawnTimer = 0; this.misses = 0; this.timeLeft = 30000;
    }
    update(sm) {
        this.timeLeft -= 16 * sm;
        if (this.timeLeft <= 0) { this.gameOver = true; return; }
        this.spawnTimer += 16 * sm;
        if (this.spawnTimer > 1000 / (1 + this.level * 0.2)) {
            this.spawnTimer = 0;
            const side = Math.floor(Math.random() * 2);
            if (!this.moles[side].up) { this.moles[side].up = true; this.moles[side].timer = 1500 / (1 + this.level * 0.2); }
        }
        this.moles.forEach(m => {
            if (m.up) { m.timer -= 16 * sm; if (m.timer <= 0) { m.up = false; this.misses++; } }
        });
        if (this.switchMode === 1 && (input.leftPressed || input.rightPressed)) {
            const mole = this.moles.find(m => m.up);
            if (mole) { mole.up = false; this.score += 10 * this.level; if (this.score % 100 === 0) this.level++; playSound('hit'); }
            return;
        }
        if (input.leftPressed && this.moles[0].up) { this.moles[0].up = false; this.score += 10 * this.level; playSound('hit');
            if (this.score % 100 === 0) this.level++; }
        else if (input.leftPressed) { playSound('low'); }
        if (input.rightPressed && this.moles[1].up) { this.moles[1].up = false; this.score += 10 * this.level; playSound('hit');
            if (this.score % 100 === 0) this.level++; }
        else if (input.rightPressed) { playSound('low'); }
    }
    draw() {
        ctx.fillStyle = '#228B22'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        const holeW = 100, holeH = 60, gap = 80;
        const lx = canvas.width / 2 - holeW - gap / 2, rx = canvas.width / 2 + gap / 2, hy = canvas.height / 2;
        [{ x: lx, m: this.moles[0] }, { x: rx, m: this.moles[1] }].forEach(({ x, m }) => {
            ctx.fillStyle = '#333'; ctx.beginPath(); ctx.ellipse(x + holeW / 2, hy + holeH / 2, holeW / 2, holeH / 3, 0, 0, Math.PI * 2); ctx.fill();
            if (m.up) { ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.ellipse(x + holeW / 2, hy, 35, 40, 0, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(x + holeW / 2 - 10, hy - 10, 5, 0, Math.PI * 2); ctx.arc(x + holeW / 2 + 10, hy - 10, 5, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = '#ff6666'; ctx.beginPath(); ctx.ellipse(x + holeW / 2, hy + 10, 8, 5, 0, 0, Math.PI * 2); ctx.fill(); }
        });
        ctx.fillStyle = '#fff'; ctx.font = '16px system-ui'; ctx.textAlign = 'center';
        ctx.fillText(`${ui("time")}: ${Math.ceil(this.timeLeft / 1000)}`, canvas.width / 2, 40);
    }
}

// GAME 20: AIR HOCKEY (left-right orientation)
class AirHockey {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.player = { x: 50, y: canvas.height / 2, r: 30, dir: 1 };
        this.ai = { x: canvas.width - 50, y: canvas.height / 2, r: 30, speed: 2.5 + this.level * 0.3 };
        this.puck = { x: canvas.width / 2, y: canvas.height / 2, r: 15, vx: 2.5, vy: (Math.random() - 0.5) * 3 };
        this.aiScore = 0;
        this.goalH = 160;
    }
    update(sm) {
        // Player paddle moves up/down
        if (this.switchMode === 1) {
            if (input.leftPressed || input.rightPressed) { this.player.dir *= -1; playSound('move'); }
            this.player.y += 5 * sm * this.player.dir;
            if (this.player.y <= this.player.r + 10) { this.player.y = this.player.r + 10; this.player.dir = 1; }
            if (this.player.y >= canvas.height - this.player.r - 10) { this.player.y = canvas.height - this.player.r - 10; this.player.dir = -1; }
        } else {
            if (input.left && this.player.y > this.player.r + 10) this.player.y -= 6 * sm;
            if (input.right && this.player.y < canvas.height - this.player.r - 10) this.player.y += 6 * sm;
        }
        // AI tracks puck vertically
        if (this.puck.y < this.ai.y - 5) this.ai.y -= this.ai.speed * sm;
        else if (this.puck.y > this.ai.y + 5) this.ai.y += this.ai.speed * sm;
        this.ai.y = Math.max(this.ai.r + 10, Math.min(canvas.height - this.ai.r - 10, this.ai.y));
        // Puck movement
        this.puck.x += this.puck.vx * sm; this.puck.y += this.puck.vy * sm;
        // Top/bottom walls
        if (this.puck.y <= this.puck.r) { this.puck.y=this.puck.r;this.puck.vy=Math.abs(this.puck.vy);playSound('hit'); }
        if (this.puck.y >= canvas.height-this.puck.r) { this.puck.y=canvas.height-this.puck.r;this.puck.vy=-Math.abs(this.puck.vy);playSound('hit'); }
        const goalTop = canvas.height / 2 - this.goalH / 2;
        const goalBot = canvas.height / 2 + this.goalH / 2;
        // Left wall (player side — concede)
        if (this.puck.x <= this.puck.r) {
            if (this.puck.y > goalTop && this.puck.y < goalBot) {
                this.aiScore++; playSound('low'); if (this.aiScore >= 5) this.gameOver = true;
                this.resetPuck(1);
            } else { this.puck.x = this.puck.r; this.puck.vx = Math.abs(this.puck.vx); playSound('hit'); }
        }
        // Right wall (AI side — score)
        if (this.puck.x >= canvas.width - this.puck.r) {
            if (this.puck.y > goalTop && this.puck.y < goalBot) {
                this.score += 10; playSound('score'); if (this.score % 50 === 0) { this.level++; this.ai.speed += 0.3; }
                this.resetPuck(-1);
            } else { this.puck.x = canvas.width - this.puck.r; this.puck.vx = -Math.abs(this.puck.vx); playSound('hit'); }
        }
        // Player paddle collision
        if (this.puck.vx < 0 && Math.hypot(this.puck.x - this.player.x, this.puck.y - this.player.y) < this.puck.r + this.player.r) {
            this.puck.x = this.player.x + this.player.r + this.puck.r;
            this.puck.vx = Math.min(5, Math.abs(this.puck.vx) + 0.2);
            this.puck.vy = (this.puck.y - this.player.y) * 0.18;
            playSound('hit');
        }
        // AI paddle collision
        if (this.puck.vx > 0 && Math.hypot(this.puck.x - this.ai.x, this.puck.y - this.ai.y) < this.puck.r + this.ai.r) {
            this.puck.x = this.ai.x - this.ai.r - this.puck.r;
            this.puck.vx = -Math.min(5, Math.abs(this.puck.vx) + 0.2);
            this.puck.vy = (this.puck.y - this.ai.y) * 0.18;
            playSound('hit');
        }
    }
    resetPuck(dir) { this.puck = { x: canvas.width / 2, y: canvas.height / 2, r: 15, vx: 2.5 * dir, vy: (Math.random() - 0.5) * 3 }; }
    draw() {
        ctx.fillStyle = '#1a3a5c'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        // Center line and circle
        ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(canvas.width / 2, 0); ctx.lineTo(canvas.width / 2, canvas.height); ctx.stroke();
        ctx.beginPath(); ctx.arc(canvas.width / 2, canvas.height / 2, 60, 0, Math.PI * 2); ctx.stroke();
        // Goal posts (walls beside goal openings)
        const gt = canvas.height / 2 - this.goalH / 2, gb = canvas.height / 2 + this.goalH / 2;
        ctx.fillStyle = '#333';
        ctx.fillRect(0, 0, 8, gt); ctx.fillRect(0, gb, 8, canvas.height - gb);
        ctx.fillRect(canvas.width - 8, 0, 8, gt); ctx.fillRect(canvas.width - 8, gb, 8, canvas.height - gb);
        // Goal zones (glowing)
        ctx.fillStyle = 'rgba(255,0,102,0.15)'; ctx.fillRect(0, gt, 20, this.goalH);
        ctx.fillStyle = 'rgba(0,255,255,0.15)'; ctx.fillRect(canvas.width - 20, gt, 20, this.goalH);
        // Player (red, left)
        ctx.fillStyle = '#ff0066'; ctx.beginPath(); ctx.arc(this.player.x, this.player.y, this.player.r, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.stroke();
        // AI (cyan, right)
        ctx.fillStyle = '#00ffff'; ctx.beginPath(); ctx.arc(this.ai.x, this.ai.y, this.ai.r, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.stroke();
        // Puck
        ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(this.puck.x, this.puck.y, this.puck.r, 0, Math.PI * 2); ctx.fill();
        // Scores
        ctx.font = '16px system-ui'; ctx.textAlign = 'center'; ctx.fillStyle = '#fff';
        ctx.fillText(`${Math.floor(this.score / 10)}`, canvas.width / 4, 40);
        ctx.fillText(`${this.aiScore}`, canvas.width * 3 / 4, 40);
    }
}

// GAME 21: LUNAR LANDER
class Lander {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.lander = { x: canvas.width / 2, y: 50, vx: 0, vy: 0, fuel: 100 };
        this.gravity = 0.008; this.thrust = 0.15;
        this.padW = 140; this.padX = canvas.width / 2 - this.padW / 2;
    }
    update(sm) {
        // Both switches fire upward rockets (no lateral movement)
        if ((input.left || input.right) && this.lander.fuel > 0) {
            this.lander.vy -= this.thrust * sm;
            this.lander.fuel -= 0.25 * sm;
            if(input.leftPressed || input.rightPressed) playSound('move');
        }
        this.lander.vy += this.gravity * sm * (1 + this.level * 0.08);
        this.lander.vy = Math.max(-3, Math.min(3, this.lander.vy));
        this.lander.y += this.lander.vy * sm;
        if (this.lander.y < 25) { this.lander.y = 25; this.lander.vy = 0; }
        // Slight horizontal drift only from vx (starts at 0, no lateral control)
        this.lander.x += this.lander.vx * sm;
        if (this.lander.x < 20) { this.lander.x = 20; this.lander.vx = 0; }
        if (this.lander.x > canvas.width - 20) { this.lander.x = canvas.width - 20; this.lander.vx = 0; }
        const groundY = canvas.height - 40;
        if (this.lander.y >= groundY - 20) {
            if (this.lander.x > this.padX && this.lander.x < this.padX + this.padW && Math.abs(this.lander.vy) < 2.5) {
                this.score += 100 * this.level; playSound('score'); this.level++;
                const newPadW = Math.max(80, 140 - this.level * 6);
                this.padX = canvas.width / 2 - newPadW / 2;
                this.padW = newPadW;
                this.lander = { x: canvas.width / 2, y: 50, vx: 0, vy: 0, fuel: Math.min(100, this.lander.fuel + 35) };
            } else this.gameOver = true;
        }
    }
    draw() {
        ctx.fillStyle = '#000022'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        for (let i = 0; i < 50; i++) { ctx.fillStyle = '#fff'; ctx.fillRect((i * 73) % canvas.width, (i * 47) % (canvas.height - 80), 1, 1); }
        ctx.fillStyle = '#444'; ctx.fillRect(0, canvas.height - 40, canvas.width, 40);
        ctx.fillStyle = '#00ff00'; ctx.fillRect(this.padX, canvas.height - 45, this.padW, 5);
        ctx.fillStyle = '#ccc'; ctx.beginPath();
        ctx.moveTo(this.lander.x, this.lander.y - 15); ctx.lineTo(this.lander.x - 15, this.lander.y + 10);
        ctx.lineTo(this.lander.x - 10, this.lander.y + 10); ctx.lineTo(this.lander.x - 12, this.lander.y + 18);
        ctx.lineTo(this.lander.x + 12, this.lander.y + 18); ctx.lineTo(this.lander.x + 10, this.lander.y + 10);
        ctx.lineTo(this.lander.x + 15, this.lander.y + 10); ctx.closePath(); ctx.fill();
        if ((input.left || input.right) && this.lander.fuel > 0) {
            ctx.fillStyle = '#ff6600'; ctx.beginPath();
            ctx.moveTo(this.lander.x - 5, this.lander.y + 18); ctx.lineTo(this.lander.x + 5, this.lander.y + 18);
            ctx.lineTo(this.lander.x, this.lander.y + 35); ctx.fill();
        }
        ctx.fillStyle = '#0f0'; ctx.fillRect(10, 10, this.lander.fuel, 15);
        ctx.strokeStyle = '#fff'; ctx.strokeRect(10, 10, 100, 15);
        ctx.fillStyle = '#fff'; ctx.font = '16px system-ui'; ctx.textAlign='left';ctx.fillText(`↕ ${this.lander.vy.toFixed(1)}`, 10, 45);
    }
}

// GAME 22: FRUIT NINJA
class Fruit {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.fruits = []; this.timer = 0; this.misses = 0;
        this.slashL = []; this.slashR = [];
    }
    update(sm) {
        this.timer += 16 * sm;
        if (this.timer > 1000 / (1 + this.level * 0.2)) {
            this.timer = 0;
            const side = Math.random() > 0.5 ? 0 : 1;
            const colors = ['#ff0000', '#ff9900', '#00ff00', '#ffff00', '#ff00ff'];
            this.fruits.push({ x: side === 0 ? canvas.width * 0.25 : canvas.width * 0.75, y: canvas.height + 30,
                vy: -12 - this.level, vx: (Math.random() - 0.5) * 4, side, r: 25 + Math.random() * 10,
                color: colors[Math.floor(Math.random() * colors.length)], sliced: false });
        }
        this.fruits = this.fruits.filter(f => {
            f.vy += 0.3 * sm; f.y += f.vy * sm; f.x += f.vx * sm;
            if (f.y > canvas.height + 50 && !f.sliced) { this.misses++; if (this.misses >= 5) this.gameOver = true; return false; }
            return f.y < canvas.height + 100;
        });
        if (this.switchMode === 1 && (input.leftPressed || input.rightPressed)) {
            this.slashL.push({t:10}); this.slashR.push({t:10});
            this.fruits.forEach(f => { if (!f.sliced && f.y < canvas.height - 50) { f.sliced = true; this.score += 10 * this.level; playSound('hit'); } });
            if (this.score >= this.level * 100) this.level++;
        } else if (input.leftPressed) { this.slashL.push({ t: 10 });
            this.fruits.forEach(f => { if (!f.sliced && f.side === 0 && f.y < canvas.height - 50) { f.sliced = true; this.score += 10 * this.level; playSound('hit');
                if (this.score % 100 === 0) this.level++; } }); }
        if (this.switchMode !== 1 && input.rightPressed) { this.slashR.push({ t: 10 });
            this.fruits.forEach(f => { if (!f.sliced && f.side === 1 && f.y < canvas.height - 50) { f.sliced = true; this.score += 10 * this.level; playSound('hit');
                if (this.score % 100 === 0) this.level++; } }); }
        this.slashL = this.slashL.filter(s => { s.t -= sm; return s.t > 0; });
        this.slashR = this.slashR.filter(s => { s.t -= sm; return s.t > 0; });
    }
    draw() {
        ctx.fillStyle = '#1a1a2e'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        if (this.slashL.length) { ctx.strokeStyle = 'rgba(255,255,255,0.8)'; ctx.lineWidth = 4;
            ctx.beginPath(); ctx.moveTo(0, canvas.height); ctx.lineTo(canvas.width / 2, 0); ctx.stroke(); }
        if (this.slashR.length) { ctx.strokeStyle = 'rgba(255,255,255,0.8)'; ctx.lineWidth = 4;
            ctx.beginPath(); ctx.moveTo(canvas.width, canvas.height); ctx.lineTo(canvas.width / 2, 0); ctx.stroke(); }
        this.fruits.forEach(f => {
            if (f.sliced) { ctx.fillStyle = 'rgba(255,255,255,0.3)'; ctx.beginPath(); ctx.arc(f.x - 10, f.y, f.r / 2, 0, Math.PI * 2); ctx.arc(f.x + 10, f.y, f.r / 2, 0, Math.PI * 2); ctx.fill(); }
            else { ctx.fillStyle = f.color; ctx.beginPath(); ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = 'rgba(255,255,255,0.3)'; ctx.beginPath(); ctx.arc(f.x - f.r * 0.3, f.y - f.r * 0.3, f.r * 0.3, 0, Math.PI * 2); ctx.fill(); }
        });
        ctx.fillStyle = '#ff0000'; ctx.font = '20px Arial';
        for (let i = 0; i < 5 - this.misses; i++) ctx.fillText('♥', 20 + i * 25, 35);
    }
}

// GAME 23: STACK TOWER
class Stack {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.blocks = [{ x: canvas.width / 2, w: 150, y: canvas.height - 30 }];
        this.current = { x: 0, w: 150, dir: 1, speed: 3 };
        this.blockH = 25; this.dropping = false;
    }
    update(sm) {
        if (this.dropping) return;
        this.current.x += this.current.dir * this.current.speed * sm * (1 + this.level * 0.1);
        if (this.current.x <= 0 || this.current.x + this.current.w >= canvas.width) this.current.dir *= -1;
        if (input.leftPressed || input.rightPressed) {
            const last = this.blocks[this.blocks.length - 1];
            const overlapL = Math.max(this.current.x, last.x - last.w / 2);
            const overlapR = Math.min(this.current.x + this.current.w, last.x + last.w / 2);
            const overlapW = overlapR - overlapL;
            if (overlapW <= 0) { this.gameOver = true; return; }
            const newX = overlapL + overlapW / 2;
            this.blocks.push({ x: newX, w: overlapW, y: last.y - this.blockH });
            this.score += Math.floor(overlapW); playSound('hit');
            if (overlapW > this.current.w * 0.95) { this.score += 50; playSound('score'); }
            this.current = { x: 0, w: overlapW, dir: 1, speed: 3 + this.blocks.length * 0.2 };
            if (this.blocks.length % 5 === 0) this.level++;
            if (this.blocks[this.blocks.length - 1].y < 100) this.blocks.forEach(b => b.y += this.blockH);
        }
    }
    draw() {
        ctx.fillStyle = '#0a0a2a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        const colors = ['#ff0066', '#ff6600', '#ffff00', '#00ff66', '#00ffff', '#6666ff'];
        this.blocks.forEach((b, i) => { ctx.fillStyle = colors[i % colors.length];
            ctx.fillRect(b.x - b.w / 2, b.y, b.w, this.blockH - 2); });
        const topY = this.blocks[this.blocks.length - 1].y - this.blockH;
        ctx.fillStyle = colors[this.blocks.length % colors.length];
        ctx.fillRect(this.current.x, topY, this.current.w, this.blockH - 2);
    }
}

// GAME 24: PENALTY KICK
class Penalty {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.keeper = { x: canvas.width / 2, targetX: canvas.width / 2, speed: 2 + this.level * 0.2 };
        this.ball = null; this.shooting = false; this.round = 0; this.misses = 0;
        this.goalW = 300; this.goalH = 100; this.goalY = 80;
        this.preparing = true; this.prepTimer = 1000;
        this.shootDir = 1; // For 1-switch mode
    }
    update(sm) {
        if (this.preparing) { this.prepTimer -= 16 * sm; if (this.prepTimer <= 0) { this.preparing = false; this.prepTimer = 1000; } return; }
        if (!this.shooting) {
            this.keeper.targetX = canvas.width / 2 + Math.sin(gameNow() / 700) * (this.goalW / 2 - 30);
            this.keeper.x += (this.keeper.targetX - this.keeper.x) * 0.06 * sm;
            if (this.switchMode === 1) {
                // 1-switch: press to shoot, alternates left/right
                if (input.leftPressed || input.rightPressed) { 
                    this.ball = { x: canvas.width / 2, y: canvas.height - 100, targetX: canvas.width / 2 + this.shootDir * this.goalW / 3, vy: -15 }; 
                    this.shooting = true; playSound('hit'); 
                    this.shootDir *= -1; // Alternate direction
                }
            } else {
                // 2-switch: left shoots left, right shoots right
                if (input.leftPressed) { this.ball = { x: canvas.width / 2, y: canvas.height - 100, targetX: canvas.width / 2 - this.goalW / 3, vy: -15 }; this.shooting = true; playSound('hit'); }
                if (input.rightPressed) { this.ball = { x: canvas.width / 2, y: canvas.height - 100, targetX: canvas.width / 2 + this.goalW / 3, vy: -15 }; this.shooting = true; playSound('hit'); }
            }
        } else {
            this.ball.y += this.ball.vy * sm;
            this.ball.x += (this.ball.targetX - this.ball.x) * 0.1 * sm;
            this.keeper.x += (this.ball.targetX - this.keeper.x) * 0.025 * sm * this.keeper.speed;
            if (this.ball.y <= this.goalY + this.goalH) {
                const saved = Math.abs(this.ball.x - this.keeper.x) < 40;
                if (saved) { this.misses++; playSound('low'); if (this.misses >= 3) this.gameOver = true; }
                else { this.score += 10 * this.level; playSound('score'); }
                this.round++; if (this.round % 5 === 0) { this.level++; this.keeper.speed += 0.2; }
                this.shooting = false; this.ball = null; this.preparing = true;
            }
        }
    }
    draw() {
        ctx.fillStyle = '#228B22'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        const gx = (canvas.width - this.goalW) / 2;
        ctx.fillStyle = '#fff'; ctx.fillRect(gx, this.goalY, this.goalW, this.goalH);
        ctx.strokeStyle = '#333'; ctx.lineWidth = 5;
        ctx.strokeRect(gx, this.goalY, this.goalW, this.goalH);
        ctx.beginPath(); ctx.moveTo(gx, this.goalY); ctx.lineTo(gx - 20, this.goalY + this.goalH + 20); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(gx + this.goalW, this.goalY); ctx.lineTo(gx + this.goalW + 20, this.goalY + this.goalH + 20); ctx.stroke();
        ctx.fillStyle = '#ff0066'; ctx.fillRect(this.keeper.x - 25, this.goalY + this.goalH - 60, 50, 60);
        ctx.fillStyle = '#ffccaa'; ctx.beginPath(); ctx.arc(this.keeper.x, this.goalY + this.goalH - 70, 15, 0, Math.PI * 2); ctx.fill();
        if (this.ball) { ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(this.ball.x, this.ball.y, 15, 0, Math.PI * 2); ctx.fill();
            ctx.strokeStyle = '#000'; ctx.lineWidth = 2; ctx.stroke(); }
        else if (!this.shooting) { ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(canvas.width / 2, canvas.height - 100, 15, 0, Math.PI * 2); ctx.fill(); }
        ctx.fillStyle = '#fff'; ctx.font = '16px system-ui'; ctx.textAlign = 'center';
        ctx.fillText(`♥ ${3 - this.misses}`, canvas.width / 2, 40);
        if (this.preparing) ctx.fillText(ui('ready'), canvas.width / 2, canvas.height / 2);
    }
}


// SOURCE: games4.js
// GAME 25: PINBALL
class Pinball {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.ball = { x: canvas.width / 2, y: canvas.height / 2, vx: 3, vy: -5, r: 10 };
        this.leftFlipper = { angle: 0.3, active: false };
        this.rightFlipper = { angle: -0.3, active: false };
        this.flipperLen = (canvas.width / 2 - 40) / (2 * Math.cos(0.3)); this.flipperY = canvas.height - 80;
        this.guides = [
            [canvas.width * 0.12, canvas.height * 0.5, canvas.width * 0.25, this.flipperY - 5],
            [canvas.width * 0.88, canvas.height * 0.5, canvas.width * 0.75, this.flipperY - 5]
        ];
        this.bumpers = [];
        this.createBumpers();
        this.balls = 3;
    }
    createBumpers() {
        this.bumpers = [
            { x: canvas.width * 0.3, y: canvas.height * 0.25, r: 25, points: 100 },
            { x: canvas.width * 0.7, y: canvas.height * 0.25, r: 25, points: 100 },
            { x: canvas.width * 0.5, y: canvas.height * 0.35, r: 30, points: 150 },
            { x: canvas.width * 0.25, y: canvas.height * 0.5, r: 20, points: 50 },
            { x: canvas.width * 0.75, y: canvas.height * 0.5, r: 20, points: 50 },
        ];
        for (let i = 0; i < this.level; i++) {
            this.bumpers.push({ x: Math.random() * (canvas.width - 100) + 50, y: Math.random() * (canvas.height * 0.4) + 50, r: 15 + Math.random() * 15, points: 75 });
        }
    }
    update(sm) {
        this.leftFlipper.active = input.left || (this.switchMode === 1 && input.right);
        this.rightFlipper.active = input.right || (this.switchMode === 1 && input.left);
        
        const targetL = this.leftFlipper.active ? -0.5 : 0.3;
        const targetR = this.rightFlipper.active ? 0.5 : -0.3;
        this.leftFlipper.angle += (targetL - this.leftFlipper.angle) * 0.3 * sm;
        this.rightFlipper.angle += (targetR - this.rightFlipper.angle) * 0.3 * sm;
        
        this.ball.vy += 0.2 * sm;
        this.ball.x += this.ball.vx * sm;
        this.ball.y += this.ball.vy * sm;
        
        if (this.ball.x <= this.ball.r) { this.ball.x = this.ball.r; this.ball.vx = Math.abs(this.ball.vx); playSound('hit'); }
        if (this.ball.x >= canvas.width - this.ball.r) { this.ball.x = canvas.width - this.ball.r; this.ball.vx = -Math.abs(this.ball.vx); playSound('hit'); }
        if (this.ball.y <= this.ball.r) { this.ball.y = this.ball.r; this.ball.vy = Math.abs(this.ball.vy); playSound('hit'); }
        // Side guide walls: deflect ball back toward flippers
        this.guides.forEach(guide => this.checkGuideCollision(guide));
        
        if (this.ball.y > canvas.height + 50) {
            this.balls--;
            if (this.balls <= 0) { this.gameOver = true; return; }
            this.ball = { x: canvas.width / 2, y: canvas.height / 2, vx: (Math.random() - 0.5) * 6, vy: -5, r: 10 };
            playSound('low');
        }
        
        // Flipper collision
        this.checkFlipperCollision(canvas.width * 0.25, this.flipperY, this.leftFlipper.angle, 1);
        this.checkFlipperCollision(canvas.width * 0.75, this.flipperY, this.rightFlipper.angle, -1);
        
        // Bumper collision
        this.bumpers.forEach(b => {
            const dx = this.ball.x - b.x, dy = this.ball.y - b.y;
            const dist = Math.hypot(dx, dy);
            if (dist < this.ball.r + b.r) {
                const angle = Math.atan2(dy, dx);
                this.ball.vx = Math.cos(angle) * 8;
                this.ball.vy = Math.sin(angle) * 8;
                this.ball.x = b.x + Math.cos(angle) * (this.ball.r + b.r + 1);
                this.ball.y = b.y + Math.sin(angle) * (this.ball.r + b.r + 1);
                this.score += b.points * this.level;
                b.hit = 5;
                playSound('score');
            }
            if (b.hit > 0) b.hit -= sm;
        });
        
        if (this.score >= this.level * 1000) { this.level++; this.createBumpers(); playSound('score'); }
    }
    checkGuideCollision([x1, y1, x2, y2]) {
        const dx = x2 - x1, dy = y2 - y1;
        const t = Math.max(0, Math.min(1, ((this.ball.x-x1)*dx+(this.ball.y-y1)*dy)/(dx*dx+dy*dy)));
        const px = x1+t*dx, py = y1+t*dy;
        const distance = Math.hypot(this.ball.x-px, this.ball.y-py);
        if (distance >= this.ball.r+2.5 || distance === 0) return;
        const nx = (this.ball.x-px)/distance, ny = (this.ball.y-py)/distance;
        const dot = this.ball.vx*nx+this.ball.vy*ny;
        this.ball.x = px+nx*(this.ball.r+3); this.ball.y = py+ny*(this.ball.r+3);
        if (dot < 0) { this.ball.vx -= 2*dot*nx; this.ball.vy -= 2*dot*ny; playSound('hit'); }
    }
    checkFlipperCollision(fx, fy, angle, dir) {
        const endX = fx + Math.cos(angle) * this.flipperLen * dir;
        const endY = fy + Math.sin(angle) * this.flipperLen;
        const dx = endX - fx, dy = endY - fy;
        const t = Math.max(0, Math.min(1, ((this.ball.x - fx) * dx + (this.ball.y - fy) * dy) / (dx * dx + dy * dy)));
        const closestX = fx + t * dx, closestY = fy + t * dy;
        const distSq = (this.ball.x - closestX) ** 2 + (this.ball.y - closestY) ** 2;
        if (distSq < (this.ball.r + 8) ** 2 && this.ball.vy > 0) {
            const flipperSpeed = (this.leftFlipper.active || this.rightFlipper.active) ? 15 : 5;
            this.ball.vy = -flipperSpeed;
            this.ball.vx += angle * 10 * dir;
            playSound('hit');
        }
    }
    draw() {
        ctx.fillStyle = '#1a1a3a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        
        // Bumpers
        this.bumpers.forEach(b => {
            ctx.fillStyle = b.hit > 0 ? '#ffffff' : '#ff6600';
            ctx.beginPath(); ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2); ctx.fill();
            ctx.strokeStyle = '#ffff00'; ctx.lineWidth = 3; ctx.stroke();
        });
        
        // Side guide walls
        ctx.strokeStyle = '#888'; ctx.lineWidth = 5; ctx.lineCap = 'butt';
        this.guides.forEach(([x1,y1,x2,y2]) => { ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke(); });

        // Flippers
        ctx.strokeStyle = '#ff0066'; ctx.lineWidth = 16; ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(canvas.width * 0.25, this.flipperY);
        ctx.lineTo(canvas.width * 0.25 + Math.cos(this.leftFlipper.angle) * this.flipperLen, this.flipperY + Math.sin(this.leftFlipper.angle) * this.flipperLen);
        ctx.stroke();
        ctx.strokeStyle = '#00ffff';
        ctx.beginPath();
        ctx.moveTo(canvas.width * 0.75, this.flipperY);
        ctx.lineTo(canvas.width * 0.75 - Math.cos(this.rightFlipper.angle) * this.flipperLen, this.flipperY + Math.sin(this.rightFlipper.angle) * this.flipperLen);
        ctx.stroke();
        
        // Ball
        ctx.fillStyle = '#c0c0c0';
        ctx.beginPath(); ctx.arc(this.ball.x, this.ball.y, this.ball.r, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = 'rgba(255,255,255,0.5)';
        ctx.beginPath(); ctx.arc(this.ball.x - 3, this.ball.y - 3, 4, 0, Math.PI * 2); ctx.fill();
        
        // Balls remaining
        ctx.fillStyle = '#fff'; ctx.font = '16px system-ui';
        ctx.fillText(`${ui("balls")}: ${this.balls}`, 10, 25);
    }
}

// GAME 26: BRICK BUILDER
class BrickBuilder {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.gridW = 10; this.gridH = 15;
        this.cellW = Math.floor((canvas.width - 40) / this.gridW);
        this.cellH = 25;
        this.offsetX = (canvas.width - this.gridW * this.cellW) / 2;
        this.offsetY = canvas.height - this.gridH * this.cellH - 20;
        this.grid = Array(this.gridH).fill(null).map(() => Array(this.gridW).fill(0));
        this.current = null;
        this.currentX = 0;
        this.currentDir = 1; // For 1-switch auto-move
        this.dropTimer = 0;
        this.dropInterval = 1000;
        this.spawnBlock();
    }
    spawnBlock() {
        const colors = ['#ff0066', '#ff6600', '#ffff00', '#00ff66', '#00ffff', '#ff00ff'];
        const widths = [1, 2, 2, 3, 3, 4];
        const w = widths[Math.floor(Math.random() * widths.length)];
        this.current = { w, color: colors[Math.floor(Math.random() * colors.length)] };
        this.currentX = Math.floor((this.gridW - w) / 2);
        
        // Check if spawn position is blocked
        for (let i = 0; i < this.current.w; i++) {
            if (this.grid[0][this.currentX + i]) { this.gameOver = true; return; }
        }
    }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: auto-move, press to drop immediately
            this.currentX += this.currentDir * 0.1 * sm;
            if (this.currentX <= 0) { this.currentX = 0; this.currentDir = 1; }
            if (this.currentX + this.current.w >= this.gridW) { this.currentX = this.gridW - this.current.w; this.currentDir = -1; }
            if (input.leftPressed || input.rightPressed) { this.dropBlock(); playSound('hit'); }
        } else {
            // 2-switch: normal left/right movement
            if (input.leftPressed && this.currentX > 0) {
                let canMove = true;
                for (let i = 0; i < this.current.w; i++) {
                    const checkY = this.getDropY(this.currentX - 1);
                    if (this.currentX - 1 + i < 0) canMove = false;
                }
                if (canMove) { this.currentX--; playSound('move'); }
            }
            if (input.rightPressed && this.currentX + this.current.w < this.gridW) {
                let canMove = true;
                if (canMove) { this.currentX++; playSound('move'); }
            }
        }
        
        if (this.switchMode === 1) return; // one-switch players choose when to drop
        this.dropTimer += 16 * sm;
        if (this.dropTimer >= this.dropInterval / (1 + this.level * 0.2)) {
            this.dropTimer = 0;
            this.dropBlock();
        }
    }
    getDropY(x) {
        x = Math.max(0, Math.min(this.gridW - this.current.w, Math.round(x)));
        for (let y = 0; y < this.gridH; y++) {
            for (let i = 0; i < this.current.w; i++) {
                if (x + i < this.gridW && this.grid[y][x + i]) return y - 1;
            }
        }
        return this.gridH - 1;
    }
    dropBlock() {
        this.currentX = Math.max(0, Math.min(this.gridW - this.current.w, Math.round(this.currentX)));
        const dropY = this.getDropY(this.currentX);
        if (dropY < 0) { this.gameOver = true; return; }
        
        for (let i = 0; i < this.current.w; i++) {
            if (this.currentX + i < this.gridW) {
                this.grid[dropY][this.currentX + i] = this.current.color;
            }
        }
        playSound('hit');
        
        // Check for complete rows
        let cleared = 0;
        for (let y = this.gridH - 1; y >= 0; y--) {
            if (this.grid[y].every(c => c !== 0)) {
                this.grid.splice(y, 1);
                this.grid.unshift(Array(this.gridW).fill(0));
                cleared++;
                y++;
            }
        }
        if (cleared > 0) {
            this.score += [0, 100, 300, 500, 800][Math.min(cleared, 4)] * this.level;
            playSound('score');
            if (this.score >= this.level * 500) this.level++;
        }
        
        this.spawnBlock();
    }
    draw() {
        ctx.fillStyle = '#0a0a1a'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        
        // Grid background
        ctx.fillStyle = '#1a1a2e';
        ctx.fillRect(this.offsetX, this.offsetY, this.gridW * this.cellW, this.gridH * this.cellH);
        
        // Grid
        for (let y = 0; y < this.gridH; y++) {
            for (let x = 0; x < this.gridW; x++) {
                if (this.grid[y][x]) {
                    ctx.fillStyle = this.grid[y][x];
                    ctx.fillRect(this.offsetX + x * this.cellW + 1, this.offsetY + y * this.cellH + 1, this.cellW - 2, this.cellH - 2);
                }
            }
        }
        
        // Current block preview (drop position)
        if (this.current) {
            const dropY = this.getDropY(this.currentX);
            ctx.fillStyle = 'rgba(255,255,255,0.2)';
            ctx.fillRect(this.offsetX + this.currentX * this.cellW, this.offsetY + dropY * this.cellH, this.current.w * this.cellW, this.cellH);
            
            // Current block at top
            ctx.fillStyle = this.current.color;
            ctx.fillRect(this.offsetX + this.currentX * this.cellW + 1, this.offsetY + 1, this.current.w * this.cellW - 2, this.cellH - 2);
        }
        
        // Border
        ctx.strokeStyle = '#ff0066'; ctx.lineWidth = 3;
        ctx.strokeRect(this.offsetX, this.offsetY, this.gridW * this.cellW, this.gridH * this.cellH);
    }
}

// GAME 27: SPACE DODGE
class SpaceDodge {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.ship = { x: canvas.width / 2, y: canvas.height - 80, w: 30, h: 40, dir: 1 };
        this.asteroids = [];
        this.powerups = [];
        this.stars = [];
        for (let i = 0; i < 50; i++) this.stars.push({ x: Math.random() * canvas.width, y: Math.random() * canvas.height, speed: 1 + Math.random() * 3 });
        this.spawnTimer = 0;
        this.shield = 0;
    }
    update(sm) {
        if (this.switchMode === 1) {
            // 1-switch: auto-move, press to change direction
            if (input.leftPressed || input.rightPressed) { this.ship.dir *= -1; playSound('move'); }
            this.ship.x += 5 * sm * this.ship.dir;
            if (this.ship.x <= this.ship.w / 2 + 10) { this.ship.x = this.ship.w / 2 + 10; this.ship.dir = 1; }
            if (this.ship.x >= canvas.width - this.ship.w / 2 - 10) { this.ship.x = canvas.width - this.ship.w / 2 - 10; this.ship.dir = -1; }
        } else {
            // 2-switch: normal left/right
            if (input.left && this.ship.x > this.ship.w / 2 + 10) this.ship.x -= 6 * sm;
            if (input.right && this.ship.x < canvas.width - this.ship.w / 2 - 10) this.ship.x += 6 * sm;
        }
        
        // Stars
        this.stars.forEach(s => { s.y += s.speed * sm * 2; if (s.y > canvas.height) { s.y = 0; s.x = Math.random() * canvas.width; } });
        
        // Spawn
        this.spawnTimer += 16 * sm;
        if (this.spawnTimer > 500 / (1 + this.level * 0.1)) {
            this.spawnTimer = 0;
            if (Math.random() > 0.15) {
                this.asteroids.push({ x: Math.random() * (canvas.width - 60) + 30, y: -40, r: 15 + Math.random() * 25, rot: Math.random() * Math.PI * 2, rotSpeed: (Math.random() - 0.5) * 0.1 });
            } else {
                this.powerups.push({ x: Math.random() * (canvas.width - 40) + 20, y: -20, type: Math.random() > 0.5 ? 'shield' : 'point' });
            }
        }
        
        // Asteroids
        this.asteroids = this.asteroids.filter(a => {
            a.y += (3 + this.level * 0.5) * sm;
            a.rot += a.rotSpeed * sm;
            if (Math.hypot(this.ship.x - a.x, this.ship.y - a.y) < a.r + 15) {
                if (this.shield > 0) { this.shield = 0; playSound('hit'); return false; }
                else { this.gameOver = true; }
            }
            return a.y < canvas.height + 50;
        });
        
        // Powerups
        this.powerups = this.powerups.filter(p => {
            p.y += 4 * sm;
            if (Math.hypot(this.ship.x - p.x, this.ship.y - p.y) < 30) {
                if (p.type === 'shield') { this.shield = 1; playSound('score'); }
                else { this.score += 50 * this.level; playSound('score'); }
                return false;
            }
            return p.y < canvas.height + 30;
        });
        
        this.score += Math.floor(sm);
        if (this.score > this.level * 500) { this.level++; playSound('score'); }
    }
    draw() {
        ctx.fillStyle = '#000011'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        
        // Stars
        this.stars.forEach(s => { ctx.fillStyle = `rgba(255,255,255,${0.3 + s.speed * 0.2})`; ctx.fillRect(s.x, s.y, 2, 2); });
        
        // Asteroids
        this.asteroids.forEach(a => {
            ctx.save(); ctx.translate(a.x, a.y); ctx.rotate(a.rot);
            ctx.fillStyle = '#666'; ctx.beginPath();
            for (let i = 0; i < 8; i++) {
                const angle = (i / 8) * Math.PI * 2;
                const r = a.r * (0.7 + Math.sin(i * 3) * 0.3);
                if (i === 0) ctx.moveTo(Math.cos(angle) * r, Math.sin(angle) * r);
                else ctx.lineTo(Math.cos(angle) * r, Math.sin(angle) * r);
            }
            ctx.closePath(); ctx.fill();
            ctx.restore();
        });
        
        // Powerups
        this.powerups.forEach(p => {
            if (p.type === 'shield') { ctx.fillStyle = '#00ffff'; ctx.beginPath(); ctx.arc(p.x, p.y, 12, 0, Math.PI * 2); ctx.fill(); }
            else { ctx.fillStyle = '#ffff00'; ctx.beginPath(); ctx.arc(p.x, p.y, 10, 0, Math.PI * 2); ctx.fill(); }
        });
        
        // Ship
        ctx.fillStyle = this.shield > 0 ? '#00ffff' : '#0088ff';
        ctx.beginPath();
        ctx.moveTo(this.ship.x, this.ship.y - this.ship.h / 2);
        ctx.lineTo(this.ship.x - this.ship.w / 2, this.ship.y + this.ship.h / 2);
        ctx.lineTo(this.ship.x, this.ship.y + this.ship.h / 4);
        ctx.lineTo(this.ship.x + this.ship.w / 2, this.ship.y + this.ship.h / 2);
        ctx.closePath(); ctx.fill();
        
        // Shield effect
        if (this.shield > 0) {
            ctx.strokeStyle = 'rgba(0,255,255,0.5)'; ctx.lineWidth = 3;
            ctx.beginPath(); ctx.arc(this.ship.x, this.ship.y, 25, 0, Math.PI * 2); ctx.stroke();
        }
        
        // Engine glow
        ctx.fillStyle = '#ff6600';
        ctx.beginPath(); ctx.moveTo(this.ship.x - 8, this.ship.y + this.ship.h / 2);
        ctx.lineTo(this.ship.x + 8, this.ship.y + this.ship.h / 2);
        ctx.lineTo(this.ship.x, this.ship.y + this.ship.h / 2 + 15 + Math.random() * 5);
        ctx.fill();
    }
}


// GAME 29: WIRE LOOP
class WireLoop {
    constructor() { this.score = 0; this.level = 1; this.gameOver = false; this.switchMode = 2; }
    init() {
        this.score = 0; this.level = 1; this.gameOver = false;
        this.generateWire();
        this.ringPos = 0; this.completedScore = 0;
        this.touching = false;
        this.touchTimer = 0;
        this.lives = 3;
    }
    generateWire() {
        this.wirePoints = [];
        const segments = 12 + this.level * 3;
        let y = canvas.height / 2;
        for (let i = 0; i <= segments; i++) {
            const x = (i / segments) * (canvas.width - 100) + 50;
            y += (Math.random() - 0.5) * (18 + this.level * 3);
            y = Math.max(130, Math.min(canvas.height - 130, y));
            this.wirePoints.push({ x, y });
        }
        this.ringY = this.wirePoints[0].y;
    }
    getWireY(pos) {
        const idx = Math.floor(pos * (this.wirePoints.length - 1));
        const nextIdx = Math.min(idx + 1, this.wirePoints.length - 1);
        const t = (pos * (this.wirePoints.length - 1)) - idx;
        return this.wirePoints[idx].y * (1 - t) + this.wirePoints[nextIdx].y * t;
    }
    getWireX(pos) {
        return pos * (canvas.width - 100) + 50;
    }
    update(sm) {
        // Manual advance: right = forward, left = back (2-switch); either = forward (1-switch)
        const advanceSpeed = 0.004 * sm * (1 + this.level * 0.05);
        if (this.switchMode === 1) {
            if (input.left || input.right) this.ringPos += advanceSpeed;
        } else {
            if (input.right) this.ringPos += advanceSpeed;
            if (input.left) this.ringPos -= advanceSpeed * 0.5;
        }
        this.ringPos = Math.max(0, Math.min(1, this.ringPos));

        // Ring Y follows wire, but with inertia (fast advance through bends = lag = touching)
        const wireY = this.getWireY(this.ringPos);
        this.ringY += (wireY - this.ringY) * 0.15 * sm;

        // Touch detection: ring center vs wire center; bigger ring means more tolerance
        const dist = Math.abs(this.ringY - wireY);
        if (dist > 28) {
            if (!this.touching) { this.touching = true; playSound('low'); }
            this.touchTimer += 16 * sm;
            if (this.touchTimer > 600) {
                this.lives--;
                this.touchTimer = 0;
                this.ringY = wireY;
                playSound('hit');
                if (this.lives <= 0) this.gameOver = true;
            }
        } else {
            this.touching = false;
            this.touchTimer = 0;
        }

        this.score = this.completedScore + Math.floor(this.ringPos * 1000);
        if (this.ringPos >= 1) {
            this.completedScore += 1000;
            this.level++;
            this.ringPos = 0;
            this.ringY = canvas.height / 2;
            this.generateWire();
            playSound('score');
        }
    }
    draw() {
        ctx.fillStyle = '#0a2a0a'; ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Wire
        ctx.strokeStyle = '#c0c0c0'; ctx.lineWidth = 8;
        ctx.beginPath();
        this.wirePoints.forEach((p, i) => { if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y); });
        ctx.stroke();

        // Ring (bigger radius = 50)
        const ringX = this.getWireX(this.ringPos);
        const ringActualY = this.ringY;

        ctx.strokeStyle = this.touching ? '#ff0000' : '#ffff00';
        ctx.lineWidth = 6;
        ctx.beginPath();
        ctx.arc(ringX, ringActualY, 50, 0, Math.PI * 2);
        ctx.stroke();

        // Handle
        ctx.strokeStyle = '#8B4513'; ctx.lineWidth = 10;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(ringX, ringActualY + 50);
        ctx.lineTo(ringX, ringActualY + 90);
        ctx.stroke();

        // Progress bar
        ctx.fillStyle = '#333'; ctx.fillRect(50, 20, canvas.width - 100, 15);
        ctx.fillStyle = '#00ff00'; ctx.fillRect(50, 20, (canvas.width - 100) * this.ringPos, 15);

        // Lives
        ctx.fillStyle = '#ff0000'; ctx.font = '16px Arial';
        for (let i = 0; i < this.lives; i++) ctx.fillText('♥', 55 + i * 25, 60);

        // Hint: which button to press
        ctx.fillStyle = '#aaa'; ctx.font = '16px system-ui'; ctx.textAlign = 'center';
        ctx.fillText(this.switchMode === 1 ? ui('forward') : '① '+ui('reverse')+'  ② '+ui('forward'), canvas.width / 2, canvas.height - 15, canvas.width - 24);

        if (this.touching) {
            ctx.fillStyle = '#ff0000'; ctx.font = '16px system-ui'; ctx.textAlign = 'center';
            ctx.fillText(ui('touching'), canvas.width / 2, canvas.height - 40);
        }
    }
}


